INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 1, 1, 'These are the words that Moses spoke to all Israel beyond the Jordan--in the wilderness, on the plain opposite Suph, between Paran and Tophel, Laban, Hazeroth, and Di-zahab.', 'en', 'NRSV-CE', 'Events at Horeb Recalled'),
(5, 'Ula', 'Deuteronomy', 1, 2, '(By the way of Mount Seir it takes eleven days to reach Kadesh-barnea from Horeb.)', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 3, 'In the fortieth year, on the first day of the eleventh month, Moses spoke to the Israelites just as the LORD had commanded him to speak to them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 4, 'This was after he had defeated King Sihon of the Amorites, who reigned in Heshbon, and King Og of Bashan, who reigned in Ashtaroth and in Edrei.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 5, 'Beyond the Jordan in the land of Moab, Moses undertook to expound this law as follows:', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 6, 'The LORD our God spoke to us at Horeb, saying, "You have stayed long enough at this mountain.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 7, 'Resume your journey, and go into the hill country of the Amorites as well as into the neighboring regions--the Arabah, the hill country, the Shephelah, the Negeb, and the seacoast--the land of the Canaanites and the Lebanon, as far as the great river, the river Euphrates.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 8, 'See, I have set the land before you; go in and take possession of the land that I swore to your ancestors, to Abraham, to Isaac, and to Jacob, to give to them and to their descendants after them."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 9, 'At that time I said to you, "I am unable by myself to bear you.', 'en', 'NRSV-CE', 'Appointment of Tribal Leaders'),
(5, 'Ula', 'Deuteronomy', 1, 10, 'The LORD your God has multiplied you, so that today you are as numerous as the stars of heaven.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 11, 'May the LORD, the God of your ancestors, increase you a thousand times more and bless you, as he has promised you!', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 12, 'But how can I bear the heavy burden of your disputes all by myself?', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 13, 'Choose for each of your tribes individuals who are wise, discerning, and reputable to be your leaders."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 14, 'You answered me, "The plan you have proposed is a good one."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 15, 'So I took the leaders of your tribes, wise and reputable individuals, and installed them as leaders over you, commanders of thousands, commanders of hundreds, commanders of fifties, commanders of tens, and officials, throughout your tribes.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 16, 'I charged your judges at that time: "Give the members of your community a fair hearing, and judge rightly between one person and another, whether citizen or resident alien.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 17, 'You must not be partial in judging: hear out the small and the great alike; you shall not be intimidated by anyone, for the judgment is God"s. Any case that is too hard for you, bring to me, and I will hear it."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 18, 'So I charged you at that time with all the things that you should do.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 19, 'Then, just as the LORD our God had ordered us, we set out from Horeb and went through all that great and terrible wilderness that you saw, on the way to the hill country of the Amorites, until we reached Kadesh-barnea.', 'en', 'NRSV-CE', 'Israel"s Refusal to Enter the Land'),
(5, 'Ula', 'Deuteronomy', 1, 20, 'I said to you, "You have reached the hill country of the Amorites, which the LORD our God is giving us.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 21, 'See, the LORD your God has given the land to you; go up, take possession, as the LORD, the God of your ancestors, has promised you; do not fear or be dismayed."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 22, 'All of you came to me and said, "Let us send men ahead of us to explore the land for us and bring back a report to us regarding the route by which we should go up and the cities we will come to."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 23, 'The plan seemed good to me, and I selected twelve of you, one from each tribe.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 24, 'They set out and went up into the hill country, and when they reached the Valley of Eshcol they spied it out', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 25, 'and gathered some of the land"s produce, which they brought down to us. They brought back a report to us, and said, "It is a good land that the LORD our God is giving us."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 26, 'But you were unwilling to go up. You rebelled against the command of the LORD your God;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 27, 'you grumbled in your tents and said, "It is because the LORD hates us that he has brought us out of the land of Egypt, to hand us over to the Amorites to destroy us.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 28, 'Where are we headed? Our kindred have made our hearts melt by reporting, "The people are stronger and taller than we; the cities are large and fortified up to heaven! We actually saw there the offspring of the Anakim!""', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 29, 'I said to you, "Have no dread or fear of them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 30, 'The LORD your God, who goes before you, is the one who will fight for you, just as he did for you in Egypt before your very eyes,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 31, 'and in the wilderness, where you saw how the LORD your God carried you, just as one carries a child, all the way that you traveled until you reached this place.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 32, 'But in spite of this, you have no trust in the LORD your God,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 33, 'who goes before you on the way to seek out a place for you to camp, in fire by night, and in the cloud by day, to show you the route you should take."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 34, 'When the LORD heard your words, he was wrathful and swore:', 'en', 'NRSV-CE', 'The Penalty for Israel"s Rebellion'),
(5, 'Ula', 'Deuteronomy', 1, 35, '"Not one of these--not one of this evil generation--shall see the good land that I swore to give to your ancestors,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 36, 'except Caleb son of Jephunneh. He shall see it, and to him and to his descendants I will give the land on which he set foot, because of his complete fidelity to the LORD."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 37, 'Even with me the LORD was angry on your account, saying, "You also shall not enter there.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 38, 'Joshua son of Nun, your assistant, shall enter there; encourage him, for he is the one who will secure Israel"s possession of it.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 39, 'And as for your little ones, who you thought would become booty, your children, who today do not yet know right from wrong, they shall enter there; to them I will give it, and they shall take possession of it.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 40, 'But as for you, journey back into the wilderness, in the direction of the Red Sea."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 41, 'You answered me, "We have sinned against the LORD! We are ready to go up and fight, just as the LORD our God commanded us." So all of you strapped on your battle gear, and thought it easy to go up into the hill country.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 42, 'The LORD said to me, "Say to them, "Do not go up and do not fight, for I am not in the midst of you; otherwise you will be defeated by your enemies.""', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 43, 'Although I told you, you would not listen. You rebelled against the command of the LORD and presumptuously went up into the hill country.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 44, 'The Amorites who lived in that hill country then came out against you and chased you as bees do. They beat you down in Seir as far as Hormah.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 45, 'When you returned and wept before the LORD, the LORD would neither heed your voice nor pay you any attention.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 1, 46, 'After you had stayed at Kadesh as many days as you did,', 'en', 'NRSV-CE', 'The Desert Years');
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 2, 1, 'we journeyed back into the wilderness, in the direction of the Red Sea, as the LORD had told me and skirted Mount Seir for many days.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 2, 2, 'Then the LORD said to me:', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 2, 3, '"You have been skirting this hill country long enough. Head north,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 2, 4, 'and charge the people as follows: You are about to pass through the territory of your kindred, the descendants of Esau, who live in Seir. They will be afraid of you, so, be very careful', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 2, 5, 'not to engage in battle with them, for I will not give you even so much as a foot"s length of their land, since I have given Mount Seir to Esau as a possession.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 2, 6, 'You shall purchase food from them for money, so that you may eat; and you shall also buy water from them for money, so that you may drink.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 2, 7, 'Surely the LORD your God has blessed you in all your undertakings; he knows your going through this great wilderness. These forty years the LORD your God has been with you; you have lacked nothing."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 2, 8, 'So we passed by our kin, the descendants of Esau who live in Seir, leaving behind the route of the Arabah, and leaving behind Elath and Ezion-geber.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 3, 1, 'When we headed up the road to Bashan, King Og of Bashan came out against us, he and all his people, for battle at Edrei.', 'en', 'NRSV-CE', 'Defeat of King Og'),
(5, 'Ula', 'Deuteronomy', 3, 2, 'The LORD said to me, "Do not fear him, for I have handed him over to you, along with his people and his land. Do to him as you did to King Sihon of the Amorites, who reigned in Heshbon."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 3, 'So the LORD our God also handed over to us King Og of Bashan and all his people. We struck him down until not a single survivor was left.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 4, 'At that time we captured all his towns; there was no citadel that we did not take from them--sixty towns, the whole region of Argob, the kingdom of Og in Bashan.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 5, 'All these were fortress towns with high walls, double gates, and bars, besides a great many villages.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 6, 'And we utterly destroyed them, as we had done to King Sihon of Heshbon, in each city utterly destroying men, women, and children.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 7, 'But all the livestock and the plunder of the towns we kept as spoil for ourselves.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 8, 'So at that time we took from the two kings of the Amorites the land beyond the Jordan, from the Wadi Arnon to Mount Hermon', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 9, '(the Sidonians call Hermon Sirion, while the Amorites call it Senir),', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 10, 'all the towns of the tableland, the whole of Gilead, and all of Bashan, as far as Salecah and Edrei, towns of Og"s kingdom in Bashan.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 11, '(Now only King Og of Bashan was left of the remnant of the Rephaim. In fact his bed, an iron bed, can still be seen in Rabbah of the Ammonites. By the common cubit it is nine cubits long and four cubits wide.)', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 12, 'As for the land that we took possession of at that time, I gave to the Reubenites and Gadites the territory north of Aroer, that is on the edge of the Wadi Arnon, as well as half the hill country of Gilead with its towns,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 13, 'and I gave to the half-tribe of Manasseh the rest of Gilead and all of Bashan, Og"s kingdom. (The whole region of Argob: all that portion of Bashan used to be called a land of Rephaim;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 14, 'Jair the Manassite acquired the whole region of Argob as far as the border of the Geshurites and the Maacathites, and he named them--that is, Bashan--after himself, Havvoth-jair, as it is to this day.)', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 15, 'To Machir I gave Gilead.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 16, 'And to the Reubenites and the Gadites I gave the territory from Gilead as far as the Wadi Arnon, with the middle of the wadi as a boundary, and up to the Jabbok, the wadi being boundary of the Ammonites;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 17, 'the Arabah also, with the Jordan and its banks, from Chinnereth down to the sea of the Arabah, the Dead Sea, with the lower slopes of Pisgah on the east.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 18, 'At that time, I charged you as follows: "Although the LORD your God has given you this land to occupy, all your troops shall cross over armed as the vanguard of your Israelite kin.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 19, 'Only your wives, your children, and your livestock--I know that you have much livestock--shall stay behind in the towns that I have given to you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 20, 'When the LORD gives rest to your kindred, as to you, and they too have occupied the land that the LORD your God is giving them beyond the Jordan, then each of you may return to the property that I have given to you."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 21, 'And I charged Joshua as well at that time, saying: "Your own eyes have seen everything that the LORD your God has done to these two kings; so the LORD will do to all the kingdoms into which you are about to cross.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 22, 'Do not fear them, for it is the LORD your God who fights for you."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 23, 'At that time, too, I entreated the LORD, saying:', 'en', 'NRSV-CE', 'Moses Views Canaan from Pisgah'),
(5, 'Ula', 'Deuteronomy', 3, 24, '"O Lord God, you have only begun to show your servant your greatness and your might; what god in heaven or on earth can perform deeds and mighty acts like yours!', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 25, 'Let me cross over to see the good land beyond the Jordan, that good hill country and the Lebanon."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 26, 'But the LORD was angry with me on your account and would not heed me. The LORD said to me, "Enough from you! Never speak to me of this matter again!', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 27, 'Go up to the top of Pisgah and look around you to the west, to the north, to the south, and to the east. Look well, for you shall not cross over this Jordan.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 28, 'But charge Joshua, and encourage and strengthen him, because it is he who shall cross over at the head of this people and who shall secure their possession of the land that you will see."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 3, 29, 'So we remained in the valley opposite Beth-peor.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 4, 1, 'So now, Israel, give heed to the statutes and ordinances that I am teaching you to observe, so that you may live to enter and occupy the land that the LORD, the God of your ancestors, is giving you.', 'en', 'NRSV-CE', 'Moses Commands Obedience'),
(5, 'Ula', 'Deuteronomy', 4, 2, 'You must neither add anything to what I command you nor take away anything from it, but keep the commandments of the LORD your God with which I am charging you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 3, 'You have seen for yourselves what the LORD did with regard to the Baal of Peor--how the LORD your God destroyed from among you everyone who followed the Baal of Peor,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 4, 'while those of you who held fast to the LORD your God are all alive today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 5, 'See, just as the LORD my God has charged me, I now teach you statutes and ordinances for you to observe in the land that you are about to enter and occupy.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 6, 'You must observe them diligently, for this will show your wisdom and discernment to the peoples, who, when they hear all these statutes, will say, "Surely this great nation is a wise and discerning people!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 7, 'For what other great nation has a god so near to it as the LORD our God is whenever we call to him?', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 8, 'And what other great nation has statutes and ordinances as just as this entire law that I am setting before you today?', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 9, 'But take care and watch yourselves closely, so as neither to forget the things that your eyes have seen nor to let them slip from your mind all the days of your life; make them known to your children and your children"s children--', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 10, 'how you once stood before the LORD your God at Horeb, when the LORD said to me, "Assemble the people for me, and I will let them hear my words, so that they may learn to fear me as long as they live on the earth, and may teach their children so";', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 11, 'you approached and stood at the foot of the mountain while the mountain was blazing up to the very heavens, shrouded in dark clouds.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 12, 'Then the LORD spoke to you out of the fire. You heard the sound of words but saw no form; there was only a voice.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 13, 'He declared to you his covenant, which he charged you to observe, that is, the ten commandments; and he wrote them on two stone tablets.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 14, 'And the LORD charged me at that time to teach you statutes and ordinances for you to observe in the land that you are about to cross into and occupy.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 15, 'Since you saw no form when the LORD spoke to you at Horeb out of the fire, take care and watch yourselves closely,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 16, 'so that you do not act corruptly by making an idol for yourselves, in the form of any figure--the likeness of male or female,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 17, 'the likeness of any animal that is on the earth, the likeness of any winged bird that flies in the air,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 18, 'the likeness of anything that creeps on the ground, the likeness of any fish that is in the water under the earth.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 19, 'And when you look up to the heavens and see the sun, the moon, and the stars, all the host of heaven, do not be led astray and bow down to them and serve them, things that the LORD your God has allotted to all the peoples everywhere under heaven.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 20, 'But the LORD has taken you and brought you out of the iron-smelter, out of Egypt, to become a people of his very own possession, as you are now.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 21, 'The LORD was angry with me because of you, and he vowed that I should not cross the Jordan and that I should not enter the good land that the LORD your God is giving for your possession.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 22, 'For I am going to die in this land without crossing over the Jordan, but you are going to cross over to take possession of that good land.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 23, 'So be careful not to forget the covenant that the LORD your God made with you, and not to make for yourselves an idol in the form of anything that the LORD your God has forbidden you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 24, 'For the LORD your God is a devouring fire, a jealous God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 25, 'When you have had children and children"s children, and become complacent in the land, if you act corruptly by making an idol in the form of anything, thus doing what is evil in the sight of the LORD your God, and provoking him to anger,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 26, 'I call heaven and earth to witness against you today that you will soon utterly perish from the land that you are crossing the Jordan to occupy; you will not live long on it, but will be utterly destroyed.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 27, 'The LORD will scatter you among the peoples; only a few of you will be left among the nations where the LORD will lead you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 28, 'There you will serve other gods made by human hands, objects of wood and stone that neither see, nor hear, nor eat, nor smell.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 29, 'From there you will seek the LORD your God, and you will find him if you search after him with all your heart and soul.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 30, 'In your distress, when all these things have happened to you in time to come, you will return to the LORD your God and heed him.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 31, 'Because the LORD your God is a merciful God, he will neither abandon you nor destroy you; he will not forget the covenant with your ancestors that he swore to them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 32, 'For ask now about former ages, long before your own, ever since the day that God created human beings on the earth; ask from one end of heaven to the other: has anything so great as this ever happened or has its like ever been heard of?', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 33, 'Has any people ever heard the voice of a god speaking out of a fire, as you have heard, and lived?', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 34, 'Or has any god ever attempted to go and take a nation for himself from the midst of another nation, by trials, by signs and wonders, by war, by a mighty hand and an outstretched arm, and by terrifying displays of power, as the LORD your God did for you in Egypt before your very eyes?', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 35, 'To you it was shown so that you would acknowledge that the LORD is God; there is no other besides him.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 36, 'From heaven he made you hear his voice to discipline you. On earth he showed you his great fire, while you heard his words coming out of the fire.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 37, 'And because he loved your ancestors, he chose their descendants after them. He brought you out of Egypt with his own presence, by his great power,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 38, 'driving out before you nations greater and mightier than yourselves, to bring you in, giving you their land for a possession, as it is still today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 39, 'So acknowledge today and take to heart that the LORD is God in heaven above and on the earth beneath; there is no other.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 40, 'Keep his statutes and his commandments, which I am commanding you today for your own well-being and that of your descendants after you, so that you may long remain in the land that the LORD your God is giving you for all time.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 41, 'Then Moses set apart on the east side of the Jordan three cities', 'en', 'NRSV-CE', 'Cities of Refuge East of the Jordan'),
(5, 'Ula', 'Deuteronomy', 4, 42, 'to which a homicide could flee, someone who unintentionally kills another person, the two not having been at enmity before; the homicide could flee to one of these cities and live:', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 43, 'Bezer in the wilderness on the tableland belonging to the Reubenites, Ramoth in Gilead belonging to the Gadites, and Golan in Bashan belonging to the Manassites.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 44, 'This is the law that Moses set before the Israelites.', 'en', 'NRSV-CE', 'Transition to the Second Address'),
(5, 'Ula', 'Deuteronomy', 4, 45, 'These are the decrees and the statutes and ordinances that Moses spoke to the Israelites when they had come out of Egypt,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 46, 'beyond the Jordan in the valley opposite Beth-peor, in the land of King Sihon of the Amorites, who reigned at Heshbon, whom Moses and the Israelites defeated when they came out of Egypt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 47, 'They occupied his land and the land of King Og of Bashan, the two kings of the Amorites on the eastern side of the Jordan:', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 48, 'from Aroer, which is on the edge of the Wadi Arnon, as far as Mount Sirion (that is, Hermon),', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 4, 49, 'together with all the Arabah on the east side of the Jordan as far as the Sea of the Arabah, under the slopes of Pisgah.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 5, 1, 'Moses convened all Israel, and said to them:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 6, 1, 'Now this is the commandment--the statutes and the ordinances--that the LORD your God charged me to teach you to observe in the land that you are about to cross into and occupy,', 'en', 'NRSV-CE', 'The Great Commandment'),
(5, 'Ula', 'Deuteronomy', 6, 2, 'so that you and your children and your children"s children may fear the LORD your God all the days of your life, and keep all his decrees and his commandments that I am commanding you, so that your days may be long.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 3, 'Hear therefore, O Israel, and observe them diligently, so that it may go well with you, and so that you may multiply greatly in a land flowing with milk and honey, as the LORD, the God of your ancestors, has promised you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 4, 'Hear, O Israel: The LORD is our God, the LORD alone.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 5, 'You shall love the LORD your God with all your heart, and with all your soul, and with all your might.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 6, 'Keep these words that I am commanding you today in your heart.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 7, 'Recite them to your children and talk about them when you are at home and when you are away, when you lie down and when you rise.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 8, 'Bind them as a sign on your hand, fix them as an emblem on your forehead,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 9, 'and write them on the doorposts of your house and on your gates.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 10, 'When the LORD your God has brought you into the land that he swore to your ancestors, to Abraham, to Isaac, and to Jacob, to give you--a land with fine, large cities that you did not build,', 'en', 'NRSV-CE', 'Caution against Disobedience'),
(5, 'Ula', 'Deuteronomy', 6, 11, 'houses filled with all sorts of goods that you did not fill, hewn cisterns that you did not hew, vineyards and olive groves that you did not plant--and when you have eaten your fill,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 12, 'take care that you do not forget the LORD, who brought you out of the land of Egypt, out of the house of slavery.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 13, 'The LORD your God you shall fear; him you shall serve, and by his name alone you shall swear.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 14, 'Do not follow other gods, any of the gods of the peoples who are all around you,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 15, 'because the LORD your God, who is present with you, is a jealous God. The anger of the LORD your God would be kindled against you and he would destroy you from the face of the earth.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 16, 'Do not put the LORD your God to the test, as you tested him at Massah.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 17, 'You must diligently keep the commandments of the LORD your God, and his decrees, and his statutes that he has commanded you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 18, 'Do what is right and good in the sight of the LORD, so that it may go well with you, and so that you may go in and occupy the good land that the LORD swore to your ancestors to give you,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 19, 'thrusting out all your enemies from before you, as the LORD has promised.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 20, 'When your children ask you in time to come, "What is the meaning of the decrees and the statutes and the ordinances that the LORD our God has commanded you?"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 21, 'then you shall say to your children, "We were Pharaoh"s slaves in Egypt, but the LORD brought us out of Egypt with a mighty hand.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 22, 'The LORD displayed before our eyes great and awesome signs and wonders against Egypt, against Pharaoh and all his household.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 23, 'He brought us out from there in order to bring us in, to give us the land that he promised on oath to our ancestors.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 24, 'Then the LORD commanded us to observe all these statutes, to fear the LORD our God, for our lasting good, so as to keep us alive, as is now the case.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 6, 25, 'If we diligently observe this entire commandment before the LORD our God, as he has commanded us, we will be in the right."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 7, 1, 'When the LORD your God brings you into the land that you are about to enter and occupy, and he clears away many nations before you--the Hittites, the Girgashites, the Amorites, the Canaanites, the Perizzites, the Hivites, and the Jebusites, seven nations mightier and more numerous than you--', 'en', 'NRSV-CE', 'A Chosen People'),
(5, 'Ula', 'Deuteronomy', 7, 2, 'and when the LORD your God gives them over to you and you defeat them, then you must utterly destroy them. Make no covenant with them and show them no mercy.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 3, 'Do not intermarry with them, giving your daughters to their sons or taking their daughters for your sons,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 4, 'for that would turn away your children from following me, to serve other gods. Then the anger of the LORD would be kindled against you, and he would destroy you quickly.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 5, 'But this is how you must deal with them: break down their altars, smash their pillars, hew down their sacred poles, and burn their idols with fire.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 6, 'For you are a people holy to the LORD your God; the LORD your God has chosen you out of all the peoples on earth to be his people, his treasured possession.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 7, 'It was not because you were more numerous than any other people that the LORD set his heart on you and chose you--for you were the fewest of all peoples.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 8, 'It was because the LORD loved you and kept the oath that he swore to your ancestors, that the LORD has brought you out with a mighty hand, and redeemed you from the house of slavery, from the hand of Pharaoh king of Egypt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 9, 'Know therefore that the LORD your God is God, the faithful God who maintains covenant loyalty with those who love him and keep his commandments, to a thousand generations,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 10, 'and who repays in their own person those who reject him. He does not delay but repays in their own person those who reject him.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 11, 'Therefore, observe diligently the commandment--the statutes and the ordinances--that I am commanding you today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 12, 'If you heed these ordinances, by diligently observing them, the LORD your God will maintain with you the covenant loyalty that he swore to your ancestors;', 'en', 'NRSV-CE', 'Blessings for Obedience'),
(5, 'Ula', 'Deuteronomy', 7, 13, 'he will love you, bless you, and multiply you; he will bless the fruit of your womb and the fruit of your ground, your grain and your wine and your oil, the increase of your cattle and the issue of your flock, in the land that he swore to your ancestors to give you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 14, 'You shall be the most blessed of peoples, with neither sterility nor barrenness among you or your livestock.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 15, 'The LORD will turn away from you every illness; all the dread diseases of Egypt that you experienced, he will not inflict on you, but he will lay them on all who hate you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 16, 'You shall devour all the peoples that the LORD your God is giving over to you, showing them no pity; you shall not serve their gods, for that would be a snare to you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 17, 'If you say to yourself, "These nations are more numerous than I; how can I dispossess them?"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 18, 'do not be afraid of them. Just remember what the LORD your God did to Pharaoh and to all Egypt,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 19, 'the great trials that your eyes saw, the signs and wonders, the mighty hand and the outstretched arm by which the LORD your God brought you out. The LORD your God will do the same to all the peoples of whom you are afraid.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 20, 'Moreover, the LORD your God will send the pestilence against them, until even the survivors and the fugitives are destroyed.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 21, 'Have no dread of them, for the LORD your God, who is present with you, is a great and awesome God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 22, 'The LORD your God will clear away these nations before you little by little; you will not be able to make a quick end of them, otherwise the wild animals would become too numerous for you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 23, 'But the LORD your God will give them over to you, and throw them into great panic, until they are destroyed.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 24, 'He will hand their kings over to you and you shall blot out their name from under heaven; no one will be able to stand against you, until you have destroyed them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 25, 'The images of their gods you shall burn with fire. Do not covet the silver or the gold that is on them and take it for yourself, because you could be ensnared by it; for it is abhorrent to the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 7, 26, 'Do not bring an abhorrent thing into your house, or you will be set apart for destruction like it. You must utterly detest and abhor it, for it is set apart for destruction.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 8, 1, 'This entire commandment that I command you today you must diligently observe, so that you may live and increase, and go in and occupy the land that the LORD promised on oath to your ancestors.', 'en', 'NRSV-CE', 'A Warning Not to Forget God in Prosperity'),
(5, 'Ula', 'Deuteronomy', 8, 2, 'Remember the long way that the LORD your God has led you these forty years in the wilderness, in order to humble you, testing you to know what was in your heart, whether or not you would keep his commandments.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 3, 'He humbled you by letting you hunger, then by feeding you with manna, with which neither you nor your ancestors were acquainted, in order to make you understand that one does not live by bread alone, but by every word that comes from the mouth of the LORD.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 4, 'The clothes on your back did not wear out and your feet did not swell these forty years.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 5, 'Know then in your heart that as a parent disciplines a child so the LORD your God disciplines you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 6, 'Therefore keep the commandments of the LORD your God, by walking in his ways and by fearing him.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 7, 'For the LORD your God is bringing you into a good land, a land with flowing streams, with springs and underground waters welling up in valleys and hills,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 8, 'a land of wheat and barley, of vines and fig trees and pomegranates, a land of olive trees and honey,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 9, 'a land where you may eat bread without scarcity, where you will lack nothing, a land whose stones are iron and from whose hills you may mine copper.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 10, 'You shall eat your fill and bless the LORD your God for the good land that he has given you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 11, 'Take care that you do not forget the LORD your God, by failing to keep his commandments, his ordinances, and his statutes, which I am commanding you today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 12, 'When you have eaten your fill and have built fine houses and live in them,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 13, 'and when your herds and flocks have multiplied, and your silver and gold is multiplied, and all that you have is multiplied,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 14, 'then do not exalt yourself, forgetting the LORD your God, who brought you out of the land of Egypt, out of the house of slavery,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 15, 'who led you through the great and terrible wilderness, an arid wasteland with poisonous snakes and scorpions. He made water flow for you from flint rock,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 16, 'and fed you in the wilderness with manna that your ancestors did not know, to humble you and to test you, and in the end to do you good.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 17, 'Do not say to yourself, "My power and the might of my own hand have gotten me this wealth."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 18, 'But remember the LORD your God, for it is he who gives you power to get wealth, so that he may confirm his covenant that he swore to your ancestors, as he is doing today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 19, 'If you do forget the LORD your God and follow other gods to serve and worship them, I solemnly warn you today that you shall surely perish.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 8, 20, 'Like the nations that the LORD is destroying before you, so shall you perish, because you would not obey the voice of the LORD your God.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 9, 1, 'Hear, O Israel! You are about to cross the Jordan today, to go in and dispossess nations larger and mightier than you, great cities, fortified to the heavens,', 'en', 'NRSV-CE', 'The Consequences of Rebelling against God'),
(5, 'Ula', 'Deuteronomy', 9, 2, 'a strong and tall people, the offspring of the Anakim, whom you know. You have heard it said of them, "Who can stand up to the Anakim?"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 3, 'Know then today that the LORD your God is the one who crosses over before you as a devouring fire; he will defeat them and subdue them before you, so that you may dispossess and destroy them quickly, as the LORD has promised you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 4, 'When the LORD your God thrusts them out before you, do not say to yourself, "It is because of my righteousness that the LORD has brought me in to occupy this land"; it is rather because of the wickedness of these nations that the LORD is dispossessing them before you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 5, 'It is not because of your righteousness or the uprightness of your heart that you are going in to occupy their land; but because of the wickedness of these nations the LORD your God is dispossessing them before you, in order to fulfill the promise that the LORD made on oath to your ancestors, to Abraham, to Isaac, and to Jacob.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 6, 'Know, then, that the LORD your God is not giving you this good land to occupy because of your righteousness; for you are a stubborn people.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 7, 'Remember and do not forget how you provoked the LORD your God to wrath in the wilderness; you have been rebellious against the LORD from the day you came out of the land of Egypt until you came to this place.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 8, 'Even at Horeb you provoked the LORD to wrath, and the LORD was so angry with you that he was ready to destroy you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 9, 'When I went up the mountain to receive the stone tablets, the tablets of the covenant that the LORD made with you, I remained on the mountain forty days and forty nights; I neither ate bread nor drank water.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 10, 'And the LORD gave me the two stone tablets written with the finger of God; on them were all the words that the LORD had spoken to you at the mountain out of the fire on the day of the assembly.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 11, 'At the end of forty days and forty nights the LORD gave me the two stone tablets, the tablets of the covenant.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 12, 'Then the LORD said to me, "Get up, go down quickly from here, for your people whom you have brought from Egypt have acted corruptly. They have been quick to turn from the way that I commanded them; they have cast an image for themselves."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 13, 'Furthermore the LORD said to me, "I have seen that this people is indeed a stubborn people.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 14, 'Let me alone that I may destroy them and blot out their name from under heaven; and I will make of you a nation mightier and more numerous than they."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 15, 'So I turned and went down from the mountain, while the mountain was ablaze; the two tablets of the covenant were in my two hands.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 16, 'Then I saw that you had indeed sinned against the LORD your God, by casting for yourselves an image of a calf; you had been quick to turn from the way that the LORD had commanded you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 17, 'So I took hold of the two tablets and flung them from my two hands, smashing them before your eyes.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 18, 'Then I lay prostrate before the LORD as before, forty days and forty nights; I neither ate bread nor drank water, because of all the sin you had committed, provoking the LORD by doing what was evil in his sight.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 19, 'For I was afraid that the anger that the LORD bore against you was so fierce that he would destroy you. But the LORD listened to me that time also.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 20, 'The LORD was so angry with Aaron that he was ready to destroy him, but I interceded also on behalf of Aaron at that same time.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 21, 'Then I took the sinful thing you had made, the calf, and burned it with fire and crushed it, grinding it thoroughly, until it was reduced to dust; and I threw the dust of it into the stream that runs down the mountain.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 22, 'At Taberah also, and at Massah, and at Kibroth-hattaavah, you provoked the LORD to wrath.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 23, 'And when the LORD sent you from Kadesh-barnea, saying, "Go up and occupy the land that I have given you," you rebelled against the command of the LORD your God, neither trusting him nor obeying him.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 24, 'You have been rebellious against the LORD as long as he has known you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 25, 'Throughout the forty days and forty nights that I lay prostrate before the LORD when the LORD intended to destroy you,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 26, 'I prayed to the LORD and said, "Lord God, do not destroy the people who are your very own possession, whom you redeemed in your greatness, whom you brought out of Egypt with a mighty hand.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 27, 'Remember your servants, Abraham, Isaac, and Jacob; pay no attention to the stubbornness of this people, their wickedness and their sin,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 28, 'otherwise the land from which you have brought us might say, "Because the LORD was not able to bring them into the land that he promised them, and because he hated them, he has brought them out to let them die in the wilderness."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 9, 29, 'For they are the people of your very own possession, whom you brought out by your great power and by your outstretched arm."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 10, 1, 'At that time the LORD said to me, "Carve out two tablets of stone like the former ones, and come up to me on the mountain, and make an ark of wood.', 'en', 'NRSV-CE', 'The Second Pair of Tablets'),
(5, 'Ula', 'Deuteronomy', 10, 2, 'I will write on the tablets the words that were on the former tablets, which you smashed, and you shall put them in the ark."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 3, 'So I made an ark of acacia wood, cut two tablets of stone like the former ones, and went up the mountain with the two tablets in my hand.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 4, 'Then he wrote on the tablets the same words as before, the ten commandments that the LORD had spoken to you on the mountain out of the fire on the day of the assembly; and the LORD gave them to me.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 5, 'So I turned and came down from the mountain, and put the tablets in the ark that I had made; and there they are, as the LORD commanded me.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 6, '(The Israelites journeyed from Beeroth-bene-jaakan to Moserah. There Aaron died, and there he was buried; his son Eleazar succeeded him as priest.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 7, 'From there they journeyed to Gudgodah, and from Gudgodah to Jotbathah, a land with flowing streams.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 8, 'At that time the LORD set apart the tribe of Levi to carry the ark of the covenant of the LORD, to stand before the LORD to minister to him, and to bless in his name, to this day.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 9, 'Therefore Levi has no allotment or inheritance with his kindred; the LORD is his inheritance, as the LORD your God promised him.)', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 10, 'I stayed on the mountain forty days and forty nights, as I had done the first time. And once again the LORD listened to me. The LORD was unwilling to destroy you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 11, 'The LORD said to me, "Get up, go on your journey at the head of the people, that they may go in and occupy the land that I swore to their ancestors to give them."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 12, 'So now, O Israel, what does the LORD your God require of you? Only to fear the LORD your God, to walk in all his ways, to love him, to serve the LORD your God with all your heart and with all your soul,', 'en', 'NRSV-CE', 'The Essence of the Law'),
(5, 'Ula', 'Deuteronomy', 10, 13, 'and to keep the commandments of the LORD your God and his decrees that I am commanding you today, for your own well-being.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 14, 'Although heaven and the heaven of heavens belong to the LORD your God, the earth with all that is in it,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 15, 'yet the LORD set his heart in love on your ancestors alone and chose you, their descendants after them, out of all the peoples, as it is today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 16, 'Circumcise, then, the foreskin of your heart, and do not be stubborn any longer.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 17, 'For the LORD your God is God of gods and Lord of lords, the great God, mighty and awesome, who is not partial and takes no bribe,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 18, 'who executes justice for the orphan and the widow, and who loves the strangers, providing them food and clothing.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 19, 'You shall also love the stranger, for you were strangers in the land of Egypt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 20, 'You shall fear the LORD your God; him alone you shall worship; to him you shall hold fast, and by his name you shall swear.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 21, 'He is your praise; he is your God, who has done for you these great and awesome things that your own eyes have seen.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 10, 22, 'Your ancestors went down to Egypt seventy persons; and now the LORD your God has made you as numerous as the stars in heaven.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 11, 1, 'You shall love the LORD your God, therefore, and keep his charge, his decrees, his ordinances, and his commandments always.', 'en', 'NRSV-CE', 'Rewards for Obedience'),
(5, 'Ula', 'Deuteronomy', 11, 2, 'Remember today that it was not your children (who have not known or seen the discipline of the LORD your God), but it is you who must acknowledge his greatness, his mighty hand and his outstretched arm,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 3, 'his signs and his deeds that he did in Egypt to Pharaoh, the king of Egypt, and to all his land;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 4, 'what he did to the Egyptian army, to their horses and chariots, how he made the water of the Red Sea flow over them as they pursued you, so that the LORD has destroyed them to this day;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 5, 'what he did to you in the wilderness, until you came to this place;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 6, 'and what he did to Dathan and Abiram, sons of Eliab son of Reuben, how in the midst of all Israel the earth opened its mouth and swallowed them up, along with their households, their tents, and every living being in their company;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 7, 'for it is your own eyes that have seen every great deed that the LORD did.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 8, 'Keep, then, this entire commandment that I am commanding you today, so that you may have strength to go in and occupy the land that you are crossing over to occupy,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 9, 'and so that you may live long in the land that the LORD swore to your ancestors to give them and to their descendants, a land flowing with milk and honey.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 10, 'For the land that you are about to enter to occupy is not like the land of Egypt, from which you have come, where you sow your seed and irrigate by foot like a vegetable garden.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 11, 'But the land that you are crossing over to occupy is a land of hills and valleys, watered by rain from the sky,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 12, 'a land that the LORD your God looks after. The eyes of the LORD your God are always on it, from the beginning of the year to the end of the year.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 13, 'If you will only heed his every commandment that I am commanding you today--loving the LORD your God, and serving him with all your heart and with all your soul--', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 14, 'then he will give the rain for your land in its season, the early rain and the later rain, and you will gather in your grain, your wine, and your oil;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 15, 'and he will give grass in your fields for your livestock, and you will eat your fill.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 16, 'Take care, or you will be seduced into turning away, serving other gods and worshiping them,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 17, 'for then the anger of the LORD will be kindled against you and he will shut up the heavens, so that there will be no rain and the land will yield no fruit; then you will perish quickly off the good land that the LORD is giving you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 18, 'You shall put these words of mine in your heart and soul, and you shall bind them as a sign on your hand, and fix them as an emblem on your forehead.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 19, 'Teach them to your children, talking about them when you are at home and when you are away, when you lie down and when you rise.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 20, 'Write them on the doorposts of your house and on your gates,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 21, 'so that your days and the days of your children may be multiplied in the land that the LORD swore to your ancestors to give them, as long as the heavens are above the earth.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 22, 'If you will diligently observe this entire commandment that I am commanding you, loving the LORD your God, walking in all his ways, and holding fast to him,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 23, 'then the LORD will drive out all these nations before you, and you will dispossess nations larger and mightier than yourselves.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 24, 'Every place on which you set foot shall be yours; your territory shall extend from the wilderness to the Lebanon and from the River, the river Euphrates, to the Western Sea.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 25, 'No one will be able to stand against you; the LORD your God will put the fear and dread of you on all the land on which you set foot, as he promised you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 26, 'See, I am setting before you today a blessing and a curse:', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 27, 'the blessing, if you obey the commandments of the LORD your God that I am commanding you today;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 28, 'and the curse, if you do not obey the commandments of the LORD your God, but turn from the way that I am commanding you today, to follow other gods that you have not known.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 29, 'When the LORD your God has brought you into the land that you are entering to occupy, you shall set the blessing on Mount Gerizim and the curse on Mount Ebal.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 30, 'As you know, they are beyond the Jordan, some distance to the west, in the land of the Canaanites who live in the Arabah, opposite Gilgal, beside the oak of Moreh.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 31, 'When you cross the Jordan to go in to occupy the land that the LORD your God is giving you, and when you occupy it and live in it,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 11, 32, 'you must diligently observe all the statutes and ordinances that I am setting before you today.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 12, 1, 'These are the statutes and ordinances that you must diligently observe in the land that the LORD, the God of your ancestors, has given you to occupy all the days that you live on the earth.', 'en', 'NRSV-CE', 'Pagan Shrines to Be Destroyed'),
(5, 'Ula', 'Deuteronomy', 12, 2, 'You must demolish completely all the places where the nations whom you are about to dispossess served their gods, on the mountain heights, on the hills, and under every leafy tree.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 3, 'Break down their altars, smash their pillars, burn their sacred poles with fire, and hew down the idols of their gods, and thus blot out their name from their places.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 4, 'You shall not worship the LORD your God in such ways.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 5, 'But you shall seek the place that the LORD your God will choose out of all your tribes as his habitation to put his name there. You shall go there,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 6, 'bringing there your burnt offerings and your sacrifices, your tithes and your donations, your votive gifts, your freewill offerings, and the firstlings of your herds and flocks.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 7, 'And you shall eat there in the presence of the LORD your God, you and your households together, rejoicing in all the undertakings in which the LORD your God has blessed you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 8, 'You shall not act as we are acting here today, all of us according to our own desires,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 9, 'for you have not yet come into the rest and the possession that the LORD your God is giving you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 10, 'When you cross over the Jordan and live in the land that the LORD your God is allotting to you, and when he gives you rest from your enemies all around so that you live in safety,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 11, 'then you shall bring everything that I command you to the place that the LORD your God will choose as a dwelling for his name: your burnt offerings and your sacrifices, your tithes and your donations, and all your choice votive gifts that you vow to the LORD.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 12, 'And you shall rejoice before the LORD your God, you together with your sons and your daughters, your male and female slaves, and the Levites who reside in your towns (since they have no allotment or inheritance with you).', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 13, 'Take care that you do not offer your burnt offerings at any place you happen to see.', 'en', 'NRSV-CE', 'A Prescribed Place of Worship'),
(5, 'Ula', 'Deuteronomy', 12, 14, 'But only at the place that the LORD will choose in one of your tribes--there you shall offer your burnt offerings and there you shall do everything I command you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 15, 'Yet whenever you desire you may slaughter and eat meat within any of your towns, according to the blessing that the LORD your God has given you; the unclean and the clean may eat of it, as they would of gazelle or deer.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 16, 'The blood, however, you must not eat; you shall pour it out on the ground like water.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 17, 'Nor may you eat within your towns the tithe of your grain, your wine, and your oil, the firstlings of your herds and your flocks, any of your votive gifts that you vow, your freewill offerings, or your donations;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 18, 'these you shall eat in the presence of the LORD your God at the place that the LORD your God will choose, you together with your son and your daughter, your male and female slaves, and the Levites resident in your towns, rejoicing in the presence of the LORD your God in all your undertakings.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 19, 'Take care that you do not neglect the Levite as long as you live in your land.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 20, 'When the LORD your God enlarges your territory, as he has promised you, and you say, "I am going to eat some meat," because you wish to eat meat, you may eat meat whenever you have the desire.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 21, 'If the place where the LORD your God will choose to put his name is too far from you, and you slaughter as I have commanded you any of your herd or flock that the LORD has given you, then you may eat within your towns whenever you desire.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 22, 'Indeed, just as gazelle or deer is eaten, so you may eat it; the unclean and the clean alike may eat it.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 23, 'Only be sure that you do not eat the blood; for the blood is the life, and you shall not eat the life with the meat.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 24, 'Do not eat it; you shall pour it out on the ground like water.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 25, 'Do not eat it, so that all may go well with you and your children after you, because you do what is right in the sight of the LORD.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 26, 'But the sacred donations that are due from you, and your votive gifts, you shall bring to the place that the LORD will choose.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 27, 'You shall present your burnt offerings, both the meat and the blood, on the altar of the LORD your God; the blood of your other sacrifices shall be poured out beside the altar of the LORD your God, but the meat you may eat.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 28, 'Be careful to obey all these words that I command you today, so that it may go well with you and with your children after you forever, because you will be doing what is good and right in the sight of the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 29, 'When the LORD your God has cut off before you the nations whom you are about to enter to dispossess them, when you have dispossessed them and live in their land,', 'en', 'NRSV-CE', 'Warning against Idolatry'),
(5, 'Ula', 'Deuteronomy', 12, 30, 'take care that you are not snared into imitating them, after they have been destroyed before you: do not inquire concerning their gods, saying, "How did these nations worship their gods? I also want to do the same."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 31, 'You must not do the same for the LORD your God, because every abhorrent thing that the LORD hates they have done for their gods. They would even burn their sons and their daughters in the fire to their gods.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 12, 32, 'You must diligently observe everything that I command you; do not add to it or take anything from it.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 13, 1, 'If prophets or those who divine by dreams appear among you and promise you omens or portents,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 2, 'and the omens or the portents declared by them take place, and they say, "Let us follow other gods" (whom you have not known) "and let us serve them,"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 3, 'you must not heed the words of those prophets or those who divine by dreams; for the LORD your God is testing you, to know whether you indeed love the LORD your God with all your heart and soul.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 4, 'The LORD your God you shall follow, him alone you shall fear, his commandments you shall keep, his voice you shall obey, him you shall serve, and to him you shall hold fast.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 5, 'But those prophets or those who divine by dreams shall be put to death for having spoken treason against the LORD your God--who brought you out of the land of Egypt and redeemed you from the house of slavery--to turn you from the way in which the LORD your God commanded you to walk. So you shall purge the evil from your midst.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 6, 'If anyone secretly entices you--even if it is your brother, your father"s son or your mother"s son, or your own son or daughter, or the wife you embrace, or your most intimate friend--saying, "Let us go worship other gods," whom neither you nor your ancestors have known,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 7, 'any of the gods of the peoples that are around you, whether near you or far away from you, from one end of the earth to the other,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 8, 'you must not yield to or heed any such persons. Show them no pity or compassion and do not shield them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 9, 'But you shall surely kill them; your own hand shall be first against them to execute them, and afterwards the hand of all the people.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 10, 'Stone them to death for trying to turn you away from the LORD your God, who brought you out of the land of Egypt, out of the house of slavery.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 11, 'Then all Israel shall hear and be afraid, and never again do any such wickedness.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 12, 'If you hear it said about one of the towns that the LORD your God is giving you to live in,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 13, 'that scoundrels from among you have gone out and led the inhabitants of the town astray, saying, "Let us go and worship other gods," whom you have not known,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 14, 'then you shall inquire and make a thorough investigation. If the charge is established that such an abhorrent thing has been done among you,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 15, 'you shall put the inhabitants of that town to the sword, utterly destroying it and everything in it--even putting its livestock to the sword.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 16, 'All of its spoil you shall gather into its public square; then burn the town and all its spoil with fire, as a whole burnt offering to the LORD your God. It shall remain a perpetual ruin, never to be rebuilt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 17, 'Do not let anything devoted to destruction stick to your hand, so that the LORD may turn from his fierce anger and show you compassion, and in his compassion multiply you, as he swore to your ancestors,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 13, 18, 'if you obey the voice of the LORD your God by keeping all his commandments that I am commanding you today, doing what is right in the sight of the LORD your God.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 14, 1, 'You are children of the LORD your God. You must not lacerate yourselves or shave your forelocks for the dead.', 'en', 'NRSV-CE', 'Pagan Practices Forbidden'),
(5, 'Ula', 'Deuteronomy', 14, 2, 'For you are a people holy to the LORD your God; it is you the LORD has chosen out of all the peoples on earth to be his people, his treasured possession.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 3, 'You shall not eat any abhorrent thing.', 'en', 'NRSV-CE', 'Clean and Unclean Foods'),
(5, 'Ula', 'Deuteronomy', 14, 4, 'These are the animals you may eat: the ox, the sheep, the goat,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 5, 'the deer, the gazelle, the roebuck, the wild goat, the ibex, the antelope, and the mountain-sheep.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 6, 'Any animal that divides the hoof and has the hoof cleft in two, and chews the cud, among the animals, you may eat.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 7, 'Yet of those that chew the cud or have the hoof cleft you shall not eat these: the camel, the hare, and the rock badger, because they chew the cud but do not divide the hoof; they are unclean for you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 8, 'And the pig, because it divides the hoof but does not chew the cud, is unclean for you. You shall not eat their meat, and you shall not touch their carcasses.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 9, 'Of all that live in water you may eat these: whatever has fins and scales you may eat.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 10, 'And whatever does not have fins and scales you shall not eat; it is unclean for you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 11, 'You may eat any clean birds.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 12, 'But these are the ones that you shall not eat: the eagle, the vulture, the osprey,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 13, 'the buzzard, the kite of any kind;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 14, 'every raven of any kind;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 15, 'the ostrich, the nighthawk, the sea gull, the hawk of any kind;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 16, 'the little owl and the great owl, the water hen', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 17, 'and the desert owl, the carrion vulture and the cormorant,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 18, 'the stork, the heron of any kind; the hoopoe and the bat.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 19, 'And all winged insects are unclean for you; they shall not be eaten.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 20, 'You may eat any clean winged creature.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 14, 21, 'You shall not eat anything that dies of itself; you may give it to aliens residing in your towns for them to eat, or you may sell it to a foreigner. For you are a people holy to the LORD your God.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 15, 1, 'Every seventh year you shall grant a remission of debts.', 'en', 'NRSV-CE', 'Laws concerning the Sabbatical Year'),
(5, 'Ula', 'Deuteronomy', 15, 2, 'And this is the manner of the remission: every creditor shall remit the claim that is held against a neighbor, not exacting it of a neighbor who is a member of the community, because the LORD"s remission has been proclaimed.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 3, 'Of a foreigner you may exact it, but you must remit your claim on whatever any member of your community owes you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 4, 'There will, however, be no one in need among you, because the LORD is sure to bless you in the land that the LORD your God is giving you as a possession to occupy,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 5, 'if only you will obey the LORD your God by diligently observing this entire commandment that I command you today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 6, 'When the LORD your God has blessed you, as he promised you, you will lend to many nations, but you will not borrow; you will rule over many nations, but they will not rule over you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 7, 'If there is among you anyone in need, a member of your community in any of your towns within the land that the LORD your God is giving you, do not be hard-hearted or tight-fisted toward your needy neighbor.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 8, 'You should rather open your hand, willingly lending enough to meet the need, whatever it may be.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 9, 'Be careful that you do not entertain a mean thought, thinking, "The seventh year, the year of remission, is near," and therefore view your needy neighbor with hostility and give nothing; your neighbor might cry to the LORD against you, and you would incur guilt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 10, 'Give liberally and be ungrudging when you do so, for on this account the LORD your God will bless you in all your work and in all that you undertake.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 11, 'Since there will never cease to be some in need on the earth, I therefore command you, "Open your hand to the poor and needy neighbor in your land."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 12, 'If a member of your community, whether a Hebrew man or a Hebrew woman, is sold to you and works for you six years, in the seventh year you shall set that person free.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 13, 'And when you send a male slave out from you a free person, you shall not send him out empty-handed.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 14, 'Provide liberally out of your flock, your threshing floor, and your wine press, thus giving to him some of the bounty with which the LORD your God has blessed you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 15, 'Remember that you were a slave in the land of Egypt, and the LORD your God redeemed you; for this reason I lay this command upon you today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 16, 'But if he says to you, "I will not go out from you," because he loves you and your household, since he is well off with you,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 15, 17, 'then you shall take an awl and thrust it through his earlobe into the door, and he shall be your slave forever.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 16, 1, 'Observe the month of Abib by keeping the passover to the LORD your God, for in the month of Abib the LORD your God brought you out of Egypt by night.', 'en', 'NRSV-CE', 'The Passover Reviewed'),
(5, 'Ula', 'Deuteronomy', 16, 2, 'You shall offer the passover sacrifice to the LORD your God, from the flock and the herd, at the place that the LORD will choose as a dwelling for his name.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 3, 'You must not eat with it anything leavened. For seven days you shall eat unleavened bread with it--the bread of affliction--because you came out of the land of Egypt in great haste, so that all the days of your life you may remember the day of your departure from the land of Egypt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 4, 'No leaven shall be seen with you in all your territory for seven days; and none of the meat of what you slaughter on the evening of the first day shall remain until morning.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 5, 'You are not permitted to offer the passover sacrifice within any of your towns that the LORD your God is giving you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 6, 'But at the place that the LORD your God will choose as a dwelling for his name, only there shall you offer the passover sacrifice, in the evening at sunset, the time of day when you departed from Egypt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 7, 'You shall cook it and eat it at the place that the LORD your God will choose; the next morning you may go back to your tents.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 8, 'For six days you shall continue to eat unleavened bread, and on the seventh day there shall be a solemn assembly for the LORD your God, when you shall do no work.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 9, 'You shall count seven weeks; begin to count the seven weeks from the time the sickle is first put to the standing grain.', 'en', 'NRSV-CE', 'The Festival of Weeks Reviewed'),
(5, 'Ula', 'Deuteronomy', 16, 10, 'Then you shall keep the festival of weeks to the LORD your God, contributing a freewill offering in proportion to the blessing that you have received from the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 11, 'Rejoice before the LORD your God--you and your sons and your daughters, your male and female slaves, the Levites resident in your towns, as well as the strangers, the orphans, and the widows who are among you--at the place that the LORD your God will choose as a dwelling for his name.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 12, 'Remember that you were a slave in Egypt, and diligently observe these statutes.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 13, 'You shall keep the festival of booths for seven days, when you have gathered in the produce from your threshing floor and your wine press.', 'en', 'NRSV-CE', 'The Festival of Booths Reviewed'),
(5, 'Ula', 'Deuteronomy', 16, 14, 'Rejoice during your festival, you and your sons and your daughters, your male and female slaves, as well as the Levites, the strangers, the orphans, and the widows resident in your towns.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 15, 'Seven days you shall keep the festival to the LORD your God at the place that the LORD will choose; for the LORD your God will bless you in all your produce and in all your undertakings, and you shall surely celebrate.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 16, 'Three times a year all your males shall appear before the LORD your God at the place that he will choose: at the festival of unleavened bread, at the festival of weeks, and at the festival of booths. They shall not appear before the LORD empty-handed;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 17, 'all shall give as they are able, according to the blessing of the LORD your God that he has given you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 18, 'You shall appoint judges and officials throughout your tribes, in all your towns that the LORD your God is giving you, and they shall render just decisions for the people.', 'en', 'NRSV-CE', 'Municipal Judges and Officers'),
(5, 'Ula', 'Deuteronomy', 16, 19, 'You must not distort justice; you must not show partiality; and you must not accept bribes, for a bribe blinds the eyes of the wise and subverts the cause of those who are in the right.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 20, 'Justice, and only justice, you shall pursue, so that you may live and occupy the land that the LORD your God is giving you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 16, 21, 'You shall not plant any tree as a sacred pole beside the altar that you make for the LORD your God;', 'en', 'NRSV-CE', 'Forbidden Forms of Worship'),
(5, 'Ula', 'Deuteronomy', 16, 22, 'nor shall you set up a stone pillar--things that the LORD your God hates.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 17, 1, 'You must not sacrifice to the LORD your God an ox or a sheep that has a defect, anything seriously wrong; for that is abhorrent to the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 2, 'If there is found among you, in one of your towns that the LORD your God is giving you, a man or woman who does what is evil in the sight of the LORD your God, and transgresses his covenant', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 3, 'by going to serve other gods and worshiping them--whether the sun or the moon or any of the host of heaven, which I have forbidden--', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 4, 'and if it is reported to you or you hear of it, and you make a thorough inquiry, and the charge is proved true that such an abhorrent thing has occurred in Israel,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 5, 'then you shall bring out to your gates that man or that woman who has committed this crime and you shall stone the man or woman to death.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 6, 'On the evidence of two or three witnesses the death sentence shall be executed; a person must not be put to death on the evidence of only one witness.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 7, 'The hands of the witnesses shall be the first raised against the person to execute the death penalty, and afterward the hands of all the people. So you shall purge the evil from your midst.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 8, 'If a judicial decision is too difficult for you to make between one kind of bloodshed and another, one kind of legal right and another, or one kind of assault and another--any such matters of dispute in your towns--then you shall immediately go up to the place that the LORD your God will choose,', 'en', 'NRSV-CE', 'Legal Decisions by Priests and Judges'),
(5, 'Ula', 'Deuteronomy', 17, 9, 'where you shall consult with the levitical priests and the judge who is in office in those days; they shall announce to you the decision in the case.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 10, 'Carry out exactly the decision that they announce to you from the place that the LORD will choose, diligently observing everything they instruct you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 11, 'You must carry out fully the law that they interpret for you or the ruling that they announce to you; do not turn aside from the decision that they announce to you, either to the right or to the left.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 12, 'As for anyone who presumes to disobey the priest appointed to minister there to the LORD your God, or the judge, that person shall die. So you shall purge the evil from Israel.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 13, 'All the people will hear and be afraid, and will not act presumptuously again.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 14, 'When you have come into the land that the LORD your God is giving you, and have taken possession of it and settled in it, and you say, "I will set a king over me, like all the nations that are around me,"', 'en', 'NRSV-CE', 'Limitations of Royal Authority'),
(5, 'Ula', 'Deuteronomy', 17, 15, 'you may indeed set over you a king whom the LORD your God will choose. One of your own community you may set as king over you; you are not permitted to put a foreigner over you, who is not of your own community.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 16, 'Even so, he must not acquire many horses for himself, or return the people to Egypt in order to acquire more horses, since the LORD has said to you, "You must never return that way again."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 17, 'And he must not acquire many wives for himself, or else his heart will turn away; also silver and gold he must not acquire in great quantity for himself.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 18, 'When he has taken the throne of his kingdom, he shall have a copy of this law written for him in the presence of the levitical priests.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 19, 'It shall remain with him and he shall read in it all the days of his life, so that he may learn to fear the LORD his God, diligently observing all the words of this law and these statutes,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 17, 20, 'neither exalting himself above other members of the community nor turning aside from the commandment, either to the right or to the left, so that he and his descendants may reign long over his kingdom in Israel.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 18, 1, 'The levitical priests, the whole tribe of Levi, shall have no allotment or inheritance within Israel. They may eat the sacrifices that are the LORD"s portion', 'en', 'NRSV-CE', 'Privileges of Priests and Levites'),
(5, 'Ula', 'Deuteronomy', 18, 2, 'but they shall have no inheritance among the other members of the community; the LORD is their inheritance, as he promised them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 3, 'This shall be the priests" due from the people, from those offering a sacrifice, whether an ox or a sheep: they shall give to the priest the shoulder, the two jowls, and the stomach.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 4, 'The first fruits of your grain, your wine, and your oil, as well as the first of the fleece of your sheep, you shall give him.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 5, 'For the LORD your God has chosen Levi out of all your tribes, to stand and minister in the name of the LORD, him and his sons for all time.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 6, 'If a Levite leaves any of your towns, from wherever he has been residing in Israel, and comes to the place that the LORD will choose (and he may come whenever he wishes),', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 7, 'then he may minister in the name of the LORD his God, like all his fellow-Levites who stand to minister there before the LORD.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 8, 'They shall have equal portions to eat, even though they have income from the sale of family possessions.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 9, 'When you come into the land that the LORD your God is giving you, you must not learn to imitate the abhorrent practices of those nations.', 'en', 'NRSV-CE', 'Child-Sacrifice, Divination, and Magic Prohibited'),
(5, 'Ula', 'Deuteronomy', 18, 10, 'No one shall be found among you who makes a son or daughter pass through fire, or who practices divination, or is a soothsayer, or an augur, or a sorcerer,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 11, 'or one who casts spells, or who consults ghosts or spirits, or who seeks oracles from the dead.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 12, 'For whoever does these things is abhorrent to the LORD; it is because of such abhorrent practices that the LORD your God is driving them out before you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 13, 'You must remain completely loyal to the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 14, 'Although these nations that you are about to dispossess do give heed to soothsayers and diviners, as for you, the LORD your God does not permit you to do so.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 15, 'The LORD your God will raise up for you a prophet like me from among your own people; you shall heed such a prophet.', 'en', 'NRSV-CE', 'A New Prophet Like Moses'),
(5, 'Ula', 'Deuteronomy', 18, 16, 'This is what you requested of the LORD your God at Horeb on the day of the assembly when you said: "If I hear the voice of the LORD my God any more, or ever again see this great fire, I will die."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 17, 'Then the LORD replied to me: "They are right in what they have said.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 18, 'I will raise up for them a prophet like you from among their own people; I will put my words in the mouth of the prophet, who shall speak to them everything that I command.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 19, 'Anyone who does not heed the words that the prophet shall speak in my name, I myself will hold accountable.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 20, 'But any prophet who speaks in the name of other gods, or who presumes to speak in my name a word that I have not commanded the prophet to speak--that prophet shall die."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 21, 'You may say to yourself, "How can we recognize a word that the LORD has not spoken?"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 18, 22, 'If a prophet speaks in the name of the LORD but the thing does not take place or prove true, it is a word that the LORD has not spoken. The prophet has spoken it presumptuously; do not be frightened by it.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 19, 1, 'When the LORD your God has cut off the nations whose land the LORD your God is giving you, and you have dispossessed them and settled in their towns and in their houses,', 'en', 'NRSV-CE', 'Laws concerning the Cities of Refuge'),
(5, 'Ula', 'Deuteronomy', 19, 2, 'you shall set apart three cities in the land that the LORD your God is giving you to possess.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 3, 'You shall calculate the distances and divide into three regions the land that the LORD your God gives you as a possession, so that any homicide can flee to one of them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 4, 'Now this is the case of a homicide who might flee there and live, that is, someone who has killed another person unintentionally when the two had not been at enmity before:', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 5, 'Suppose someone goes into the forest with another to cut wood, and when one of them swings the ax to cut down a tree, the head slips from the handle and strikes the other person who then dies; the killer may flee to one of these cities and live.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 6, 'But if the distance is too great, the avenger of blood in hot anger might pursue and overtake and put the killer to death, although a death sentence was not deserved, since the two had not been at enmity before.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 7, 'Therefore I command you: You shall set apart three cities.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 8, 'If the LORD your God enlarges your territory, as he swore to your ancestors--and he will give you all the land that he promised your ancestors to give you,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 9, 'provided you diligently observe this entire commandment that I command you today, by loving the LORD your God and walking always in his ways--then you shall add three more cities to these three,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 10, 'so that the blood of an innocent person may not be shed in the land that the LORD your God is giving you as an inheritance, thereby bringing bloodguilt upon you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 11, 'But if someone at enmity with another lies in wait and attacks and takes the life of that person, and flees into one of these cities,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 12, 'then the elders of the killer"s city shall send to have the culprit taken from there and handed over to the avenger of blood to be put to death.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 13, 'Show no pity; you shall purge the guilt of innocent blood from Israel, so that it may go well with you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 14, 'You must not move your neighbor"s boundary marker, set up by former generations, on the property that will be allotted to you in the land that the LORD your God is giving you to possess.', 'en', 'NRSV-CE', 'Property Boundaries'),
(5, 'Ula', 'Deuteronomy', 19, 15, 'A single witness shall not suffice to convict a person of any crime or wrongdoing in connection with any offense that may be committed. Only on the evidence of two or three witnesses shall a charge be sustained.', 'en', 'NRSV-CE', 'Law concerning Witnesses'),
(5, 'Ula', 'Deuteronomy', 19, 16, 'If a malicious witness comes forward to accuse someone of wrongdoing,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 17, 'then both parties to the dispute shall appear before the LORD, before the priests and the judges who are in office in those days,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 18, 'and the judges shall make a thorough inquiry. If the witness is a false witness, having testified falsely against another,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 19, 'then you shall do to the false witness just as the false witness had meant to do to the other. So you shall purge the evil from your midst.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 20, 'The rest shall hear and be afraid, and a crime such as this shall never again be committed among you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 19, 21, 'Show no pity: life for life, eye for eye, tooth for tooth, hand for hand, foot for foot.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 20, 1, 'When you go out to war against your enemies, and see horses and chariots, an army larger than your own, you shall not be afraid of them; for the LORD your God is with you, who brought you up from the land of Egypt.', 'en', 'NRSV-CE', 'Rules of Warfare'),
(5, 'Ula', 'Deuteronomy', 20, 2, 'Before you engage in battle, the priest shall come forward and speak to the troops,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 3, 'and shall say to them: "Hear, O Israel! Today you are drawing near to do battle against your enemies. Do not lose heart, or be afraid, or panic, or be in dread of them;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 4, 'for it is the LORD your God who goes with you, to fight for you against your enemies, to give you victory."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 5, 'Then the officials shall address the troops, saying, "Has anyone built a new house but not dedicated it? He should go back to his house, or he might die in the battle and another dedicate it.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 6, 'Has anyone planted a vineyard but not yet enjoyed its fruit? He should go back to his house, or he might die in the battle and another be first to enjoy its fruit.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 7, 'Has anyone become engaged to a woman but not yet married her? He should go back to his house, or he might die in the battle and another marry her."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 8, 'The officials shall continue to address the troops, saying, "Is anyone afraid or disheartened? He should go back to his house, or he might cause the heart of his comrades to melt like his own."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 9, 'When the officials have finished addressing the troops, then the commanders shall take charge of them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 10, 'When you draw near to a town to fight against it, offer it terms of peace.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 11, 'If it accepts your terms of peace and surrenders to you, then all the people in it shall serve you at forced labor.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 12, 'If it does not submit to you peacefully, but makes war against you, then you shall besiege it;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 13, 'and when the LORD your God gives it into your hand, you shall put all its males to the sword.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 14, 'You may, however, take as your booty the women, the children, livestock, and everything else in the town, all its spoil. You may enjoy the spoil of your enemies, which the LORD your God has given you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 15, 'Thus you shall treat all the towns that are very far from you, which are not towns of the nations here.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 16, 'But as for the towns of these peoples that the LORD your God is giving you as an inheritance, you must not let anything that breathes remain alive.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 17, 'You shall annihilate them--the Hittites and the Amorites, the Canaanites and the Perizzites, the Hivites and the Jebusites--just as the LORD your God has commanded,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 18, 'so that they may not teach you to do all the abhorrent things that they do for their gods, and you thus sin against the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 19, 'If you besiege a town for a long time, making war against it in order to take it, you must not destroy its trees by wielding an ax against them. Although you may take food from them, you must not cut them down. Are trees in the field human beings that they should come under siege from you?', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 20, 20, 'You may destroy only the trees that you know do not produce food; you may cut them down for use in building siegeworks against the town that makes war with you, until it falls.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 21, 1, 'If, in the land that the LORD your God is giving you to possess, a body is found lying in open country, and it is not known who struck the person down,', 'en', 'NRSV-CE', 'Law concerning Murder by Persons Unknown'),
(5, 'Ula', 'Deuteronomy', 21, 2, 'then your elders and your judges shall come out to measure the distances to the towns that are near the body.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 3, 'The elders of the town nearest the body shall take a heifer that has never been worked, one that has not pulled in the yoke;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 4, 'the elders of that town shall bring the heifer down to a wadi with running water, which is neither plowed nor sown, and shall break the heifer"s neck there in the wadi.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 5, 'Then the priests, the sons of Levi, shall come forward, for the LORD your God has chosen them to minister to him and to pronounce blessings in the name of the LORD, and by their decision all cases of dispute and assault shall be settled.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 6, 'All the elders of that town nearest the body shall wash their hands over the heifer whose neck was broken in the wadi,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 7, 'and they shall declare: "Our hands did not shed this blood, nor were we witnesses to it.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 8, 'Absolve, O LORD, your people Israel, whom you redeemed; do not let the guilt of innocent blood remain in the midst of your people Israel." Then they will be absolved of bloodguilt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 9, 'So you shall purge the guilt of innocent blood from your midst, because you must do what is right in the sight of the LORD.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 10, 'When you go out to war against your enemies, and the LORD your God hands them over to you and you take them captive,', 'en', 'NRSV-CE', 'Female Captives'),
(5, 'Ula', 'Deuteronomy', 21, 11, 'suppose you see among the captives a beautiful woman whom you desire and want to marry,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 12, 'and so you bring her home to your house: she shall shave her head, pare her nails,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 13, 'discard her captive"s garb, and shall remain in your house a full month, mourning for her father and mother; after that you may go in to her and be her husband, and she shall be your wife.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 14, 'But if you are not satisfied with her, you shall let her go free and not sell her for money. You must not treat her as a slave, since you have dishonored her.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 15, 'If a man has two wives, one of them loved and the other disliked, and if both the loved and the disliked have borne him sons, the firstborn being the son of the one who is disliked,', 'en', 'NRSV-CE', 'The Right of the Firstborn'),
(5, 'Ula', 'Deuteronomy', 21, 16, 'then on the day when he wills his possessions to his sons, he is not permitted to treat the son of the loved as the firstborn in preference to the son of the disliked, who is the firstborn.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 17, 'He must acknowledge as firstborn the son of the one who is disliked, giving him a double portion of all that he has; since he is the first issue of his virility, the right of the firstborn is his.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 18, 'If someone has a stubborn and rebellious son who will not obey his father and mother, who does not heed them when they discipline him,', 'en', 'NRSV-CE', 'Rebellious Children'),
(5, 'Ula', 'Deuteronomy', 21, 19, 'then his father and his mother shall take hold of him and bring him out to the elders of his town at the gate of that place.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 20, 'They shall say to the elders of his town, "This son of ours is stubborn and rebellious. He will not obey us. He is a glutton and a drunkard."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 21, 'Then all the men of the town shall stone him to death. So you shall purge the evil from your midst; and all Israel will hear, and be afraid.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 21, 22, 'When someone is convicted of a crime punishable by death and is executed, and you hang him on a tree,', 'en', 'NRSV-CE', 'Miscellaneous Laws'),
(5, 'Ula', 'Deuteronomy', 21, 23, 'his corpse must not remain all night upon the tree; you shall bury him that same day, for anyone hung on a tree is under God"s curse. You must not defile the land that the LORD your God is giving you for possession.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 22, 1, 'You shall not watch your neighbor"s ox or sheep straying away and ignore them; you shall take them back to their owner.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 2, 'If the owner does not reside near you or you do not know who the owner is, you shall bring it to your own house, and it shall remain with you until the owner claims it; then you shall return it.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 3, 'You shall do the same with a neighbor"s donkey; you shall do the same with a neighbor"s garment; and you shall do the same with anything else that your neighbor loses and you find. You may not withhold your help.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 4, 'You shall not see your neighbor"s donkey or ox fallen on the road and ignore it; you shall help to lift it up.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 5, 'A woman shall not wear a man"s apparel, nor shall a man put on a woman"s garment; for whoever does such things is abhorrent to the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 6, 'If you come on a bird"s nest, in any tree or on the ground, with fledglings or eggs, with the mother sitting on the fledglings or on the eggs, you shall not take the mother with the young.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 7, 'Let the mother go, taking only the young for yourself, in order that it may go well with you and you may live long.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 8, 'When you build a new house, you shall make a parapet for your roof; otherwise you might have bloodguilt on your house, if anyone should fall from it.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 9, 'You shall not sow your vineyard with a second kind of seed, or the whole yield will have to be forfeited, both the crop that you have sown and the yield of the vineyard itself.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 10, 'You shall not plow with an ox and a donkey yoked together.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 11, 'You shall not wear clothes made of wool and linen woven together.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 12, 'You shall make tassels on the four corners of the cloak with which you cover yourself.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 13, 'Suppose a man marries a woman, but after going in to her, he dislikes her', 'en', 'NRSV-CE', 'Laws concerning Sexual Relations'),
(5, 'Ula', 'Deuteronomy', 22, 14, 'and makes up charges against her, slandering her by saying, "I married this woman; but when I lay with her, I did not find evidence of her virginity."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 15, 'The father of the young woman and her mother shall then submit the evidence of the young woman"s virginity to the elders of the city at the gate.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 16, 'The father of the young woman shall say to the elders: "I gave my daughter in marriage to this man but he dislikes her;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 17, 'now he has made up charges against her, saying, "I did not find evidence of your daughter"s virginity." But here is the evidence of my daughter"s virginity." Then they shall spread out the cloth before the elders of the town.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 18, 'The elders of that town shall take the man and punish him;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 19, 'they shall fine him one hundred shekels of silver (which they shall give to the young woman"s father) because he has slandered a virgin of Israel. She shall remain his wife; he shall not be permitted to divorce her as long as he lives.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 20, 'If, however, this charge is true, that evidence of the young woman"s virginity was not found,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 21, 'then they shall bring the young woman out to the entrance of her father"s house and the men of her town shall stone her to death, because she committed a disgraceful act in Israel by prostituting herself in her father"s house. So you shall purge the evil from your midst.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 22, 'If a man is caught lying with the wife of another man, both of them shall die, the man who lay with the woman as well as the woman. So you shall purge the evil from Israel.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 23, 'If there is a young woman, a virgin already engaged to be married, and a man meets her in the town and lies with her,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 24, 'you shall bring both of them to the gate of that town and stone them to death, the young woman because she did not cry for help in the town and the man because he violated his neighbor"s wife. So you shall purge the evil from your midst.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 25, 'But if the man meets the engaged woman in the open country, and the man seizes her and lies with her, then only the man who lay with her shall die.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 26, 'You shall do nothing to the young woman; the young woman has not committed an offense punishable by death, because this case is like that of someone who attacks and murders a neighbor.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 27, 'Since he found her in the open country, the engaged woman may have cried for help, but there was no one to rescue her.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 28, 'If a man meets a virgin who is not engaged, and seizes her and lies with her, and they are caught in the act,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 29, 'the man who lay with her shall give fifty shekels of silver to the young woman"s father, and she shall become his wife. Because he violated her he shall not be permitted to divorce her as long as he lives.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 22, 30, 'A man shall not marry his father"s wife, thereby violating his father"s rights.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 23, 1, 'No one whose testicles are crushed or whose penis is cut off shall be admitted to the assembly of the LORD.', 'en', 'NRSV-CE', 'Those Excluded from the Assembly'),
(5, 'Ula', 'Deuteronomy', 23, 2, 'Those born of an illicit union shall not be admitted to the assembly of the LORD. Even to the tenth generation, none of their descendants shall be admitted to the assembly of the LORD.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 3, 'No Ammonite or Moabite shall be admitted to the assembly of the LORD. Even to the tenth generation, none of their descendants shall be admitted to the assembly of the LORD,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 4, 'because they did not meet you with food and water on your journey out of Egypt, and because they hired against you Balaam son of Beor, from Pethor of Mesopotamia, to curse you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 5, '(Yet the LORD your God refused to heed Balaam; the LORD your God turned the curse into a blessing for you, because the LORD your God loved you.)', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 6, 'You shall never promote their welfare or their prosperity as long as you live.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 7, 'You shall not abhor any of the Edomites, for they are your kin. You shall not abhor any of the Egyptians, because you were an alien residing in their land.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 8, 'The children of the third generation that are born to them may be admitted to the assembly of the LORD.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 9, 'When you are encamped against your enemies you shall guard against any impropriety.', 'en', 'NRSV-CE', 'Sanitary, Ritual, and Humanitarian Precepts'),
(5, 'Ula', 'Deuteronomy', 23, 10, 'If one of you becomes unclean because of a nocturnal emission, then he shall go outside the camp; he must not come within the camp.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 11, 'When evening comes, he shall wash himself with water, and when the sun has set, he may come back into the camp.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 12, 'You shall have a designated area outside the camp to which you shall go.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 13, 'With your utensils you shall have a trowel; when you relieve yourself outside, you shall dig a hole with it and then cover up your excrement.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 14, 'Because the LORD your God travels along with your camp, to save you and to hand over your enemies to you, therefore your camp must be holy, so that he may not see anything indecent among you and turn away from you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 15, 'Slaves who have escaped to you from their owners shall not be given back to them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 16, 'They shall reside with you, in your midst, in any place they choose in any one of your towns, wherever they please; you shall not oppress them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 17, 'None of the daughters of Israel shall be a temple prostitute; none of the sons of Israel shall be a temple prostitute.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 18, 'You shall not bring the fee of a prostitute or the wages of a male prostitute into the house of the LORD your God in payment for any vow, for both of these are abhorrent to the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 19, 'You shall not charge interest on loans to another Israelite, interest on money, interest on provisions, interest on anything that is lent.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 20, 'On loans to a foreigner you may charge interest, but on loans to another Israelite you may not charge interest, so that the LORD your God may bless you in all your undertakings in the land that you are about to enter and possess.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 21, 'If you make a vow to the LORD your God, do not postpone fulfilling it; for the LORD your God will surely require it of you, and you would incur guilt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 22, 'But if you refrain from vowing, you will not incur guilt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 23, 'Whatever your lips utter you must diligently perform, just as you have freely vowed to the LORD your God with your own mouth.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 24, 'If you go into your neighbor"s vineyard, you may eat your fill of grapes, as many as you wish, but you shall not put any in a container.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 23, 25, 'If you go into your neighbor"s standing grain, you may pluck the ears with your hand, but you shall not put a sickle to your neighbor"s standing grain.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 24, 1, 'Suppose a man enters into marriage with a woman, but she does not please him because he finds something objectionable about her, and so he writes her a certificate of divorce, puts it in her hand, and sends her out of his house; she then leaves his house', 'en', 'NRSV-CE', 'Laws concerning Marriage and Divorce'),
(5, 'Ula', 'Deuteronomy', 24, 2, 'and goes off to become another man"s wife.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 3, 'Then suppose the second man dislikes her, writes her a bill of divorce, puts it in her hand, and sends her out of his house (or the second man who married her dies);', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 4, 'her first husband, who sent her away, is not permitted to take her again to be his wife after she has been defiled; for that would be abhorrent to the LORD, and you shall not bring guilt on the land that the LORD your God is giving you as a possession.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 5, 'When a man is newly married, he shall not go out with the army or be charged with any related duty. He shall be free at home one year, to be happy with the wife whom he has married.', 'en', 'NRSV-CE', 'Miscellaneous Laws'),
(5, 'Ula', 'Deuteronomy', 24, 6, 'No one shall take a mill or an upper millstone in pledge, for that would be taking a life in pledge.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 7, 'If someone is caught kidnaping another Israelite, enslaving or selling the Israelite, then that kidnaper shall die. So you shall purge the evil from your midst.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 8, 'Guard against an outbreak of a leprous skin disease by being very careful; you shall carefully observe whatever the levitical priests instruct you, just as I have commanded them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 9, 'Remember what the LORD your God did to Miriam on your journey out of Egypt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 10, 'When you make your neighbor a loan of any kind, you shall not go into the house to take the pledge.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 11, 'You shall wait outside, while the person to whom you are making the loan brings the pledge out to you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 12, 'If the person is poor, you shall not sleep in the garment given you as the pledge.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 13, 'You shall give the pledge back by sunset, so that your neighbor may sleep in the cloak and bless you; and it will be to your credit before the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 14, 'You shall not withhold the wages of poor and needy laborers, whether other Israelites or aliens who reside in your land in one of your towns.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 15, 'You shall pay them their wages daily before sunset, because they are poor and their livelihood depends on them; otherwise they might cry to the LORD against you, and you would incur guilt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 16, 'Parents shall not be put to death for their children, nor shall children be put to death for their parents; only for their own crimes may persons be put to death.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 17, 'You shall not deprive a resident alien or an orphan of justice; you shall not take a widow"s garment in pledge.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 18, 'Remember that you were a slave in Egypt and the LORD your God redeemed you from there; therefore I command you to do this.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 19, 'When you reap your harvest in your field and forget a sheaf in the field, you shall not go back to get it; it shall be left for the alien, the orphan, and the widow, so that the LORD your God may bless you in all your undertakings.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 20, 'When you beat your olive trees, do not strip what is left; it shall be for the alien, the orphan, and the widow.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 21, 'When you gather the grapes of your vineyard, do not glean what is left; it shall be for the alien, the orphan, and the widow.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 24, 22, 'Remember that you were a slave in the land of Egypt; therefore I am commanding you to do this.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 25, 1, 'Suppose two persons have a dispute and enter into litigation, and the judges decide between them, declaring one to be in the right and the other to be in the wrong.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 2, 'If the one in the wrong deserves to be flogged, the judge shall make that person lie down and be beaten in his presence with the number of lashes proportionate to the offense.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 3, 'Forty lashes may be given but not more; if more lashes than these are given, your neighbor will be degraded in your sight.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 4, 'You shall not muzzle an ox while it is treading out the grain.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 5, 'When brothers reside together, and one of them dies and has no son, the wife of the deceased shall not be married outside the family to a stranger. Her husband"s brother shall go in to her, taking her in marriage, and performing the duty of a husband"s brother to her,', 'en', 'NRSV-CE', 'Levirate Marriage'),
(5, 'Ula', 'Deuteronomy', 25, 6, 'and the firstborn whom she bears shall succeed to the name of the deceased brother, so that his name may not be blotted out of Israel.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 7, 'But if the man has no desire to marry his brother"s widow, then his brother"s widow shall go up to the elders at the gate and say, "My husband"s brother refuses to perpetuate his brother"s name in Israel; he will not perform the duty of a husband"s brother to me."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 8, 'Then the elders of his town shall summon him and speak to him. If he persists, saying, "I have no desire to marry her,"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 9, 'then his brother"s wife shall go up to him in the presence of the elders, pull his sandal off his foot, spit in his face, and declare, "This is what is done to the man who does not build up his brother"s house."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 10, 'Throughout Israel his family shall be known as "the house of him whose sandal was pulled off."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 11, 'If men get into a fight with one another, and the wife of one intervenes to rescue her husband from the grip of his opponent by reaching out and seizing his genitals,', 'en', 'NRSV-CE', 'Various Commands'),
(5, 'Ula', 'Deuteronomy', 25, 12, 'you shall cut off her hand; show no pity.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 13, 'You shall not have in your bag two kinds of weights, large and small.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 14, 'You shall not have in your house two kinds of measures, large and small.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 15, 'You shall have only a full and honest weight; you shall have only a full and honest measure, so that your days may be long in the land that the LORD your God is giving you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 16, 'For all who do such things, all who act dishonestly, are abhorrent to the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 17, 'Remember what Amalek did to you on your journey out of Egypt,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 18, 'how he attacked you on the way, when you were faint and weary, and struck down all who lagged behind you; he did not fear God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 25, 19, 'Therefore when the LORD your God has given you rest from all your enemies on every hand, in the land that the LORD your God is giving you as an inheritance to possess, you shall blot out the remembrance of Amalek from under heaven; do not forget.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 26, 1, 'When you have come into the land that the LORD your God is giving you as an inheritance to possess, and you possess it, and settle in it,', 'en', 'NRSV-CE', 'First Fruits and Tithes'),
(5, 'Ula', 'Deuteronomy', 26, 2, 'you shall take some of the first of all the fruit of the ground, which you harvest from the land that the LORD your God is giving you, and you shall put it in a basket and go to the place that the LORD your God will choose as a dwelling for his name.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 3, 'You shall go to the priest who is in office at that time, and say to him, "Today I declare to the LORD your God that I have come into the land that the LORD swore to our ancestors to give us."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 4, 'When the priest takes the basket from your hand and sets it down before the altar of the LORD your God,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 5, 'you shall make this response before the LORD your God: "A wandering Aramean was my ancestor; he went down into Egypt and lived there as an alien, few in number, and there he became a great nation, mighty and populous.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 6, 'When the Egyptians treated us harshly and afflicted us, by imposing hard labor on us,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 7, 'we cried to the LORD, the God of our ancestors; the LORD heard our voice and saw our affliction, our toil, and our oppression.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 8, 'The LORD brought us out of Egypt with a mighty hand and an outstretched arm, with a terrifying display of power, and with signs and wonders;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 9, 'and he brought us into this place and gave us this land, a land flowing with milk and honey.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 10, 'So now I bring the first of the fruit of the ground that you, O LORD, have given me." You shall set it down before the LORD your God and bow down before the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 11, 'Then you, together with the Levites and the aliens who reside among you, shall celebrate with all the bounty that the LORD your God has given to you and to your house.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 12, 'When you have finished paying all the tithe of your produce in the third year (which is the year of the tithe), giving it to the Levites, the aliens, the orphans, and the widows, so that they may eat their fill within your towns,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 13, 'then you shall say before the LORD your God: "I have removed the sacred portion from the house, and I have given it to the Levites, the resident aliens, the orphans, and the widows, in accordance with your entire commandment that you commanded me; I have neither transgressed nor forgotten any of your commandments:', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 14, 'I have not eaten of it while in mourning; I have not removed any of it while I was unclean; and I have not offered any of it to the dead. I have obeyed the LORD my God, doing just as you commanded me.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 15, 'Look down from your holy habitation, from heaven, and bless your people Israel and the ground that you have given us, as you swore to our ancestors--a land flowing with milk and honey."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 16, 'This very day the LORD your God is commanding you to observe these statutes and ordinances; so observe them diligently with all your heart and with all your soul.', 'en', 'NRSV-CE', 'Concluding Exhortation'),
(5, 'Ula', 'Deuteronomy', 26, 17, 'Today you have obtained the LORD"s agreement: to be your God; and for you to walk in his ways, to keep his statutes, his commandments, and his ordinances, and to obey him.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 18, 'Today the LORD has obtained your agreement: to be his treasured people, as he promised you, and to keep his commandments;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 26, 19, 'for him to set you high above all nations that he has made, in praise and in fame and in honor; and for you to be a people holy to the LORD your God, as he promised.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 27, 1, 'Then Moses and the elders of Israel charged all the people as follows: Keep the entire commandment that I am commanding you today.', 'en', 'NRSV-CE', 'The Inscribed Stones and Altar on Mount Ebal'),
(5, 'Ula', 'Deuteronomy', 27, 2, 'On the day that you cross over the Jordan into the land that the LORD your God is giving you, you shall set up large stones and cover them with plaster.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 3, 'You shall write on them all the words of this law when you have crossed over, to enter the land that the LORD your God is giving you, a land flowing with milk and honey, as the LORD, the God of your ancestors, promised you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 4, 'So when you have crossed over the Jordan, you shall set up these stones, about which I am commanding you today, on Mount Ebal, and you shall cover them with plaster.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 5, 'And you shall build an altar there to the LORD your God, an altar of stones on which you have not used an iron tool.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 6, 'You must build the altar of the LORD your God of unhewn stones. Then offer up burnt offerings on it to the LORD your God,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 7, 'make sacrifices of well-being, and eat them there, rejoicing before the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 8, 'You shall write on the stones all the words of this law very clearly.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 9, 'Then Moses and the levitical priests spoke to all Israel, saying: Keep silence and hear, O Israel! This very day you have become the people of the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 10, 'Therefore obey the LORD your God, observing his commandments and his statutes that I am commanding you today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 11, 'The same day Moses charged the people as follows:', 'en', 'NRSV-CE', 'Twelve Curses'),
(5, 'Ula', 'Deuteronomy', 27, 12, 'When you have crossed over the Jordan, these shall stand on Mount Gerizim for the blessing of the people: Simeon, Levi, Judah, Issachar, Joseph, and Benjamin.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 13, 'And these shall stand on Mount Ebal for the curse: Reuben, Gad, Asher, Zebulun, Dan, and Naphtali.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 14, 'Then the Levites shall declare in a loud voice to all the Israelites:', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 15, '"Cursed be anyone who makes an idol or casts an image, anything abhorrent to the LORD, the work of an artisan, and sets it up in secret." All the people shall respond, saying, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 16, '"Cursed be anyone who dishonors father or mother." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 17, '"Cursed be anyone who moves a neighbor"s boundary marker." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 18, '"Cursed be anyone who misleads a blind person on the road." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 19, '"Cursed be anyone who deprives the alien, the orphan, and the widow of justice." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 20, '"Cursed be anyone who lies with his father"s wife, because he has violated his father"s rights." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 21, '"Cursed be anyone who lies with any animal." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 22, '"Cursed be anyone who lies with his sister, whether the daughter of his father or the daughter of his mother." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 23, '"Cursed be anyone who lies with his mother-in-law." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 24, '"Cursed be anyone who strikes down a neighbor in secret." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 25, '"Cursed be anyone who takes a bribe to shed innocent blood." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 27, 26, '"Cursed be anyone who does not uphold the words of this law by observing them." All the people shall say, "Amen!"', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 28, 1, 'If you will only obey the LORD your God, by diligently observing all his commandments that I am commanding you today, the LORD your God will set you high above all the nations of the earth;', 'en', 'NRSV-CE', 'Blessings for Obedience'),
(5, 'Ula', 'Deuteronomy', 28, 2, 'all these blessings shall come upon you and overtake you, if you obey the LORD your God:', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 3, 'Blessed shall you be in the city, and blessed shall you be in the field.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 4, 'Blessed shall be the fruit of your womb, the fruit of your ground, and the fruit of your livestock, both the increase of your cattle and the issue of your flock.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 5, 'Blessed shall be your basket and your kneading bowl.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 6, 'Blessed shall you be when you come in, and blessed shall you be when you go out.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 7, 'The LORD will cause your enemies who rise against you to be defeated before you; they shall come out against you one way, and flee before you seven ways.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 8, 'The LORD will command the blessing upon you in your barns, and in all that you undertake; he will bless you in the land that the LORD your God is giving you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 9, 'The LORD will establish you as his holy people, as he has sworn to you, if you keep the commandments of the LORD your God and walk in his ways.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 10, 'All the peoples of the earth shall see that you are called by the name of the LORD, and they shall be afraid of you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 11, 'The LORD will make you abound in prosperity, in the fruit of your womb, in the fruit of your livestock, and in the fruit of your ground in the land that the LORD swore to your ancestors to give you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 12, 'The LORD will open for you his rich storehouse, the heavens, to give the rain of your land in its season and to bless all your undertakings. You will lend to many nations, but you will not borrow.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 13, 'The LORD will make you the head, and not the tail; you shall be only at the top, and not at the bottom--if you obey the commandments of the LORD your God, which I am commanding you today, by diligently observing them,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 14, 'and if you do not turn aside from any of the words that I am commanding you today, either to the right or to the left, following other gods to serve them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 15, 'But if you will not obey the LORD your God by diligently observing all his commandments and decrees, which I am commanding you today, then all these curses shall come upon you and overtake you:', 'en', 'NRSV-CE', 'Warnings against Disobedience'),
(5, 'Ula', 'Deuteronomy', 28, 16, 'Cursed shall you be in the city, and cursed shall you be in the field.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 17, 'Cursed shall be your basket and your kneading bowl.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 18, 'Cursed shall be the fruit of your womb, the fruit of your ground, the increase of your cattle and the issue of your flock.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 19, 'Cursed shall you be when you come in, and cursed shall you be when you go out.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 20, 'The LORD will send upon you disaster, panic, and frustration in everything you attempt to do, until you are destroyed and perish quickly, on account of the evil of your deeds, because you have forsaken me.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 21, 'The LORD will make the pestilence cling to you until it has consumed you off the land that you are entering to possess.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 22, 'The LORD will afflict you with consumption, fever, inflammation, with fiery heat and drought, and with blight and mildew; they shall pursue you until you perish.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 23, 'The sky over your head shall be bronze, and the earth under you iron.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 24, 'The LORD will change the rain of your land into powder, and only dust shall come down upon you from the sky until you are destroyed.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 25, 'The LORD will cause you to be defeated before your enemies; you shall go out against them one way and flee before them seven ways. You shall become an object of horror to all the kingdoms of the earth.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 26, 'Your corpses shall be food for every bird of the air and animal of the earth, and there shall be no one to frighten them away.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 27, 'The LORD will afflict you with the boils of Egypt, with ulcers, scurvy, and itch, of which you cannot be healed.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 28, 'The LORD will afflict you with madness, blindness, and confusion of mind;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 29, 'you shall grope about at noon as blind people grope in darkness, but you shall be unable to find your way; and you shall be continually abused and robbed, without anyone to help.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 30, 'You shall become engaged to a woman, but another man shall lie with her. You shall build a house, but not live in it. You shall plant a vineyard, but not enjoy its fruit.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 31, 'Your ox shall be butchered before your eyes, but you shall not eat of it. Your donkey shall be stolen in front of you, and shall not be restored to you. Your sheep shall be given to your enemies, without anyone to help you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 32, 'Your sons and daughters shall be given to another people, while you look on; you will strain your eyes looking for them all day but be powerless to do anything.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 33, 'A people whom you do not know shall eat up the fruit of your ground and of all your labors; you shall be continually abused and crushed,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 34, 'and driven mad by the sight that your eyes shall see.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 35, 'The LORD will strike you on the knees and on the legs with grievous boils of which you cannot be healed, from the sole of your foot to the crown of your head.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 36, 'The LORD will bring you, and the king whom you set over you, to a nation that neither you nor your ancestors have known, where you shall serve other gods, of wood and stone.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 37, 'You shall become an object of horror, a proverb, and a byword among all the peoples where the LORD will lead you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 38, 'You shall carry much seed into the field but shall gather little in, for the locust shall consume it.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 39, 'You shall plant vineyards and dress them, but you shall neither drink the wine nor gather the grapes, for the worm shall eat them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 40, 'You shall have olive trees throughout all your territory, but you shall not anoint yourself with the oil, for your olives shall drop off.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 41, 'You shall have sons and daughters, but they shall not remain yours, for they shall go into captivity.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 42, 'All your trees and the fruit of your ground the cicada shall take over.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 43, 'Aliens residing among you shall ascend above you higher and higher, while you shall descend lower and lower.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 44, 'They shall lend to you but you shall not lend to them; they shall be the head and you shall be the tail.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 45, 'All these curses shall come upon you, pursuing and overtaking you until you are destroyed, because you did not obey the LORD your God, by observing the commandments and the decrees that he commanded you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 46, 'They shall be among you and your descendants as a sign and a portent forever.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 47, 'Because you did not serve the LORD your God joyfully and with gladness of heart for the abundance of everything,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 48, 'therefore you shall serve your enemies whom the LORD will send against you, in hunger and thirst, in nakedness and lack of everything. He will put an iron yoke on your neck until he has destroyed you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 49, 'The LORD will bring a nation from far away, from the end of the earth, to swoop down on you like an eagle, a nation whose language you do not understand,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 50, 'a grim-faced nation showing no respect to the old or favor to the young.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 51, 'It shall consume the fruit of your livestock and the fruit of your ground until you are destroyed, leaving you neither grain, wine, and oil, nor the increase of your cattle and the issue of your flock, until it has made you perish.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 52, 'It shall besiege you in all your towns until your high and fortified walls, in which you trusted, come down throughout your land; it shall besiege you in all your towns throughout the land that the LORD your God has given you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 53, 'In the desperate straits to which the enemy siege reduces you, you will eat the fruit of your womb, the flesh of your own sons and daughters whom the LORD your God has given you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 54, 'Even the most refined and gentle of men among you will begrudge food to his own brother, to the wife whom he embraces, and to the last of his remaining children,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 55, 'giving to none of them any of the flesh of his children whom he is eating, because nothing else remains to him, in the desperate straits to which the enemy siege will reduce you in all your towns.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 56, 'She who is the most refined and gentle among you, so gentle and refined that she does not venture to set the sole of her foot on the ground, will begrudge food to the husband whom she embraces, to her own son, and to her own daughter,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 57, 'begrudging even the afterbirth that comes out from between her thighs, and the children that she bears, because she is eating them in secret for lack of anything else, in the desperate straits to which the enemy siege will reduce you in your towns.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 58, 'If you do not diligently observe all the words of this law that are written in this book, fearing this glorious and awesome name, the LORD your God,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 59, 'then the LORD will overwhelm both you and your offspring with severe and lasting afflictions and grievous and lasting maladies.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 60, 'He will bring back upon you all the diseases of Egypt, of which you were in dread, and they shall cling to you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 61, 'Every other malady and affliction, even though not recorded in the book of this law, the LORD will inflict on you until you are destroyed.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 62, 'Although once you were as numerous as the stars in heaven, you shall be left few in number, because you did not obey the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 63, 'And just as the LORD took delight in making you prosperous and numerous, so the LORD will take delight in bringing you to ruin and destruction; you shall be plucked off the land that you are entering to possess.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 64, 'The LORD will scatter you among all peoples, from one end of the earth to the other; and there you shall serve other gods, of wood and stone, which neither you nor your ancestors have known.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 65, 'Among those nations you shall find no ease, no resting place for the sole of your foot. There the LORD will give you a trembling heart, failing eyes, and a languishing spirit.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 66, 'Your life shall hang in doubt before you; night and day you shall be in dread, with no assurance of your life.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 67, 'In the morning you shall say, "If only it were evening!" and at evening you shall say, "If only it were morning!"--because of the dread that your heart shall feel and the sights that your eyes shall see.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 28, 68, 'The LORD will bring you back in ships to Egypt, by a route that I promised you would never see again; and there you shall offer yourselves for sale to your enemies as male and female slaves, but there will be no buyer.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 29, 1, 'These are the words of the covenant that the LORD commanded Moses to make with the Israelites in the land of Moab, in addition to the covenant that he had made with them at Horeb.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 2, 'Moses summoned all Israel and said to them: You have seen all that the LORD did before your eyes in the land of Egypt, to Pharaoh and to all his servants and to all his land,', 'en', 'NRSV-CE', 'The Covenant Renewed in Moab'),
(5, 'Ula', 'Deuteronomy', 29, 3, 'the great trials that your eyes saw, the signs, and those great wonders.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 4, 'But to this day the LORD has not given you a mind to understand, or eyes to see, or ears to hear.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 5, 'I have led you forty years in the wilderness. The clothes on your back have not worn out, and the sandals on your feet have not worn out;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 6, 'you have not eaten bread, and you have not drunk wine or strong drink--so that you may know that I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 7, 'When you came to this place, King Sihon of Heshbon and King Og of Bashan came out against us for battle, but we defeated them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 8, 'We took their land and gave it as an inheritance to the Reubenites, the Gadites, and the half-tribe of Manasseh.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 9, 'Therefore diligently observe the words of this covenant, in order that you may succeed in everything that you do.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 10, 'You stand assembled today, all of you, before the LORD your God--the leaders of your tribes, your elders, and your officials, all the men of Israel,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 11, 'your children, your women, and the aliens who are in your camp, both those who cut your wood and those who draw your water--', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 12, 'to enter into the covenant of the LORD your God, sworn by an oath, which the LORD your God is making with you today;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 13, 'in order that he may establish you today as his people, and that he may be your God, as he promised you and as he swore to your ancestors, to Abraham, to Isaac, and to Jacob.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 14, 'I am making this covenant, sworn by an oath, not only with you who stand here with us today before the LORD our God,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 15, 'but also with those who are not here with us today.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 16, 'You know how we lived in the land of Egypt, and how we came through the midst of the nations through which you passed.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 17, 'You have seen their detestable things, the filthy idols of wood and stone, of silver and gold, that were among them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 18, 'It may be that there is among you a man or woman, or a family or tribe, whose heart is already turning away from the LORD our God to serve the gods of those nations. It may be that there is among you a root sprouting poisonous and bitter growth.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 19, 'All who hear the words of this oath and bless themselves, thinking in their hearts, "We are safe even though we go our own stubborn ways" (thus bringing disaster on moist and dry alike)--', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 20, 'the LORD will be unwilling to pardon them, for the LORD"s anger and passion will smoke against them. All the curses written in this book will descend on them, and the LORD will blot out their names from under heaven.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 21, 'The LORD will single them out from all the tribes of Israel for calamity, in accordance with all the curses of the covenant written in this book of the law.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 22, 'The next generation, your children who rise up after you, as well as the foreigner who comes from a distant country, will see the devastation of that land and the afflictions with which the LORD has afflicted it--', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 23, 'all its soil burned out by sulfur and salt, nothing planted, nothing sprouting, unable to support any vegetation, like the destruction of Sodom and Gomorrah, Admah and Zeboiim, which the LORD destroyed in his fierce anger--', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 24, 'they and indeed all the nations will wonder, "Why has the LORD done thus to this land? What caused this great display of anger?"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 25, 'They will conclude, "It is because they abandoned the covenant of the LORD, the God of their ancestors, which he made with them when he brought them out of the land of Egypt.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 26, 'They turned and served other gods, worshiping them, gods whom they had not known and whom he had not allotted to them;', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 27, 'so the anger of the LORD was kindled against that land, bringing on it every curse written in this book.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 28, 'The LORD uprooted them from their land in anger, fury, and great wrath, and cast them into another land, as is now the case."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 29, 29, 'The secret things belong to the LORD our God, but the revealed things belong to us and to our children forever, to observe all the words of this law.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 30, 1, 'When all these things have happened to you, the blessings and the curses that I have set before you, if you call them to mind among all the nations where the LORD your God has driven you,', 'en', 'NRSV-CE', 'God"s Fidelity Assured'),
(5, 'Ula', 'Deuteronomy', 30, 2, 'and return to the LORD your God, and you and your children obey him with all your heart and with all your soul, just as I am commanding you today,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 3, 'then the LORD your God will restore your fortunes and have compassion on you, gathering you again from all the peoples among whom the LORD your God has scattered you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 4, 'Even if you are exiled to the ends of the world, from there the LORD your God will gather you, and from there he will bring you back.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 5, 'The LORD your God will bring you into the land that your ancestors possessed, and you will possess it; he will make you more prosperous and numerous than your ancestors.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 6, 'Moreover, the LORD your God will circumcise your heart and the heart of your descendants, so that you will love the LORD your God with all your heart and with all your soul, in order that you may live.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 7, 'The LORD your God will put all these curses on your enemies and on the adversaries who took advantage of you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 8, 'Then you shall again obey the LORD, observing all his commandments that I am commanding you today,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 9, 'and the LORD your God will make you abundantly prosperous in all your undertakings, in the fruit of your body, in the fruit of your livestock, and in the fruit of your soil. For the LORD will again take delight in prospering you, just as he delighted in prospering your ancestors,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 10, 'when you obey the LORD your God by observing his commandments and decrees that are written in this book of the law, because you turn to the LORD your God with all your heart and with all your soul.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 11, 'Surely, this commandment that I am commanding you today is not too hard for you, nor is it too far away.', 'en', 'NRSV-CE', 'Exhortation to Choose Life'),
(5, 'Ula', 'Deuteronomy', 30, 12, 'It is not in heaven, that you should say, "Who will go up to heaven for us, and get it for us so that we may hear it and observe it?"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 13, 'Neither is it beyond the sea, that you should say, "Who will cross to the other side of the sea for us, and get it for us so that we may hear it and observe it?"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 14, 'No, the word is very near to you; it is in your mouth and in your heart for you to observe.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 15, 'See, I have set before you today life and prosperity, death and adversity.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 16, 'If you obey the commandments of the LORD your God that I am commanding you today, by loving the LORD your God, walking in his ways, and observing his commandments, decrees, and ordinances, then you shall live and become numerous, and the LORD your God will bless you in the land that you are entering to possess.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 17, 'But if your heart turns away and you do not hear, but are led astray to bow down to other gods and serve them,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 18, 'I declare to you today that you shall perish; you shall not live long in the land that you are crossing the Jordan to enter and possess.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 19, 'I call heaven and earth to witness against you today that I have set before you life and death, blessings and curses. Choose life so that you and your descendants may live,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 30, 20, 'loving the LORD your God, obeying him, and holding fast to him; for that means life to you and length of days, so that you may live in the land that the LORD swore to give to your ancestors, to Abraham, to Isaac, and to Jacob.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 31, 1, 'When Moses had finished speaking all these words to all Israel,', 'en', 'NRSV-CE', 'Joshua Becomes Moses" Successor'),
(5, 'Ula', 'Deuteronomy', 31, 2, 'he said to them: "I am now one hundred twenty years old. I am no longer able to get about, and the LORD has told me, "You shall not cross over this Jordan."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 3, 'The LORD your God himself will cross over before you. He will destroy these nations before you, and you shall dispossess them. Joshua also will cross over before you, as the LORD promised.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 4, 'The LORD will do to them as he did to Sihon and Og, the kings of the Amorites, and to their land, when he destroyed them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 5, 'The LORD will give them over to you and you shall deal with them in full accord with the command that I have given to you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 6, 'Be strong and bold; have no fear or dread of them, because it is the LORD your God who goes with you; he will not fail you or forsake you."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 7, 'Then Moses summoned Joshua and said to him in the sight of all Israel: "Be strong and bold, for you are the one who will go with this people into the land that the LORD has sworn to their ancestors to give them; and you will put them in possession of it.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 8, 'It is the LORD who goes before you. He will be with you; he will not fail you or forsake you. Do not fear or be dismayed."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 9, 'Then Moses wrote down this law, and gave it to the priests, the sons of Levi, who carried the ark of the covenant of the LORD, and to all the elders of Israel.', 'en', 'NRSV-CE', 'The Law to Be Read Every Seventh Year'),
(5, 'Ula', 'Deuteronomy', 31, 10, 'Moses commanded them: "Every seventh year, in the scheduled year of remission, during the festival of booths,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 11, 'when all Israel comes to appear before the LORD your God at the place that he will choose, you shall read this law before all Israel in their hearing.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 12, 'Assemble the people--men, women, and children, as well as the aliens residing in your towns--so that they may hear and learn to fear the LORD your God and to observe diligently all the words of this law,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 13, 'and so that their children, who have not known it, may hear and learn to fear the LORD your God, as long as you live in the land that you are crossing over the Jordan to possess."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 14, 'The LORD said to Moses, "Your time to die is near; call Joshua and present yourselves in the tent of meeting, so that I may commission him." So Moses and Joshua went and presented themselves in the tent of meeting,', 'en', 'NRSV-CE', 'Moses and Joshua Receive God"s Charge'),
(5, 'Ula', 'Deuteronomy', 31, 15, 'and the LORD appeared at the tent in a pillar of cloud; the pillar of cloud stood at the entrance to the tent.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 16, 'The LORD said to Moses, "Soon you will lie down with your ancestors. Then this people will begin to prostitute themselves to the foreign gods in their midst, the gods of the land into which they are going; they will forsake me, breaking my covenant that I have made with them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 17, 'My anger will be kindled against them in that day. I will forsake them and hide my face from them; they will become easy prey, and many terrible troubles will come upon them. In that day they will say, "Have not these troubles come upon us because our God is not in our midst?"', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 18, 'On that day I will surely hide my face on account of all the evil they have done by turning to other gods.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 19, 'Now therefore write this song, and teach it to the Israelites; put it in their mouths, in order that this song may be a witness for me against the Israelites.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 20, 'For when I have brought them into the land flowing with milk and honey, which I promised on oath to their ancestors, and they have eaten their fill and grown fat, they will turn to other gods and serve them, despising me and breaking my covenant.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 21, 'And when many terrible troubles come upon them, this song will confront them as a witness, because it will not be lost from the mouths of their descendants. For I know what they are inclined to do even now, before I have brought them into the land that I promised them on oath."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 22, 'That very day Moses wrote this song and taught it to the Israelites.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 23, 'Then the LORD commissioned Joshua son of Nun and said, "Be strong and bold, for you shall bring the Israelites into the land that I promised them; I will be with you."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 24, 'When Moses had finished writing down in a book the words of this law to the very end,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 25, 'Moses commanded the Levites who carried the ark of the covenant of the LORD, saying,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 26, '"Take this book of the law and put it beside the ark of the covenant of the LORD your God; let it remain there as a witness against you.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 27, 'For I know well how rebellious and stubborn you are. If you already have been so rebellious toward the LORD while I am still alive among you, how much more after my death!', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 28, 'Assemble to me all the elders of your tribes and your officials, so that I may recite these words in their hearing and call heaven and earth to witness against them.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 29, 'For I know that after my death you will surely act corruptly, turning aside from the way that I have commanded you. In time to come trouble will befall you, because you will do what is evil in the sight of the LORD, provoking him to anger through the work of your hands."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 31, 30, 'Then Moses recited the words of this song, to the very end, in the hearing of the whole assembly of Israel:', 'en', 'NRSV-CE', 'The Song of Moses');
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 32, 1, 'Give ear, O heavens, and I will speak;  
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 33, 1, 'This is the blessing with which Moses, the man of God, blessed the Israelites before his death.', 'en', 'NRSV-CE', 'Moses" Final Blessing on Israel'),
(5, 'Ula', 'Deuteronomy', 33, 2, 'He said:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(5, 'Ula', 'Deuteronomy', 34, 1, 'Then Moses went up from the plains of Moab to Mount Nebo, to the top of Pisgah, which is opposite Jericho, and the LORD showed him the whole land: Gilead as far as Dan,', 'en', 'NRSV-CE', 'Moses Dies and Is Buried in the Land of Moab'),
(5, 'Ula', 'Deuteronomy', 34, 2, 'all Naphtali, the land of Ephraim and Manasseh, all the land of Judah as far as the Western Sea,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 3, 'the Negeb, and the Plain--that is, the valley of Jericho, the city of palm trees--as far as Zoar.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 4, 'The LORD said to him, "This is the land of which I swore to Abraham, to Isaac, and to Jacob, saying, "I will give it to your descendants"; I have let you see it with your eyes, but you shall not cross over there."', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 5, 'Then Moses, the servant of the LORD, died there in the land of Moab, at the LORD"s command.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 6, 'He was buried in a valley in the land of Moab, opposite Beth-peor, but no one knows his burial place to this day.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 7, 'Moses was one hundred twenty years old when he died; his sight was unimpaired and his vigor had not abated.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 8, 'The Israelites wept for Moses in the plains of Moab thirty days; then the period of mourning for Moses was ended.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 9, 'Joshua son of Nun was full of the spirit of wisdom, because Moses had laid his hands on him; and the Israelites obeyed him, doing as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 10, 'Never since has there arisen a prophet in Israel like Moses, whom the LORD knew face to face.', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 11, 'He was unequaled for all the signs and wonders that the LORD sent him to perform in the land of Egypt, against Pharaoh and all his servants and his entire land,', 'en', 'NRSV-CE', NULL),
(5, 'Ula', 'Deuteronomy', 34, 12, 'and for all the mighty deeds and all the terrifying displays of power that Moses performed in the sight of all Israel.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 1, 1, 'After the death of Moses the servant of the LORD, the LORD spoke to Joshua son of Nun, Moses" assistant, saying,', 'en', 'NRSV-CE', 'God"s Commission to Joshua'),
(6, 'Yos', 'Joshua', 1, 2, '"My servant Moses is dead. Now proceed to cross the Jordan, you and all this people, into the land that I am giving to them, to the Israelites.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 3, 'Every place that the sole of your foot will tread upon I have given to you, as I promised to Moses.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 4, 'From the wilderness and the Lebanon as far as the great river, the river Euphrates, all the land of the Hittites, to the Great Sea in the west shall be your territory.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 5, 'No one shall be able to stand against you all the days of your life. As I was with Moses, so I will be with you; I will not fail you or forsake you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 6, 'Be strong and courageous; for you shall put this people in possession of the land that I swore to their ancestors to give them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 7, 'Only be strong and very courageous, being careful to act in accordance with all the law that my servant Moses commanded you; do not turn from it to the right hand or to the left, so that you may be successful wherever you go.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 8, 'This book of the law shall not depart out of your mouth; you shall meditate on it day and night, so that you may be careful to act in accordance with all that is written in it. For then you shall make your way prosperous, and then you shall be successful.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 9, 'I hereby command you: Be strong and courageous; do not be frightened or dismayed, for the LORD your God is with you wherever you go."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 10, 'Then Joshua commanded the officers of the people,', 'en', 'NRSV-CE', 'Preparations for the Invasion'),
(6, 'Yos', 'Joshua', 1, 11, '"Pass through the camp, and command the people: "Prepare your provisions; for in three days you are to cross over the Jordan, to go in to take possession of the land that the LORD your God gives you to possess.""', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 12, 'To the Reubenites, the Gadites, and the half-tribe of Manasseh Joshua said,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 13, '"Remember the word that Moses the servant of the LORD commanded you, saying, "The LORD your God is providing you a place of rest, and will give you this land."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 14, 'Your wives, your little ones, and your livestock shall remain in the land that Moses gave you beyond the Jordan. But all the warriors among you shall cross over armed before your kindred and shall help them,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 15, 'until the LORD gives rest to your kindred as well as to you, and they too take possession of the land that the LORD your God is giving them. Then you shall return to your own land and take possession of it, the land that Moses the servant of the LORD gave you beyond the Jordan to the east."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 16, 'They answered Joshua: "All that you have commanded us we will do, and wherever you send us we will go.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 17, 'Just as we obeyed Moses in all things, so we will obey you. Only may the LORD your God be with you, as he was with Moses!', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 1, 18, 'Whoever rebels against your orders and disobeys your words, whatever you command, shall be put to death. Only be strong and courageous."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 2, 1, 'Then Joshua son of Nun sent two men secretly from Shittim as spies, saying, "Go, view the land, especially Jericho." So they went, and entered the house of a prostitute whose name was Rahab, and spent the night there.', 'en', 'NRSV-CE', 'Spies Sent to Jericho'),
(6, 'Yos', 'Joshua', 2, 2, 'The king of Jericho was told, "Some Israelites have come here tonight to search out the land."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 3, 'Then the king of Jericho sent orders to Rahab, "Bring out the men who have come to you, who entered your house, for they have come only to search out the whole land."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 4, 'But the woman took the two men and hid them. Then she said, "True, the men came to me, but I did not know where they came from.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 5, 'And when it was time to close the gate at dark, the men went out. Where the men went I do not know. Pursue them quickly, for you can overtake them."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 6, 'She had, however, brought them up to the roof and hidden them with the stalks of flax that she had laid out on the roof.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 7, 'So the men pursued them on the way to the Jordan as far as the fords. As soon as the pursuers had gone out, the gate was shut.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 8, 'Before they went to sleep, she came up to them on the roof', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 9, 'and said to the men: "I know that the LORD has given you the land, and that dread of you has fallen on us, and that all the inhabitants of the land melt in fear before you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 10, 'For we have heard how the LORD dried up the water of the Red Sea before you when you came out of Egypt, and what you did to the two kings of the Amorites that were beyond the Jordan, to Sihon and Og, whom you utterly destroyed.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 11, 'As soon as we heard it, our hearts melted, and there was no courage left in any of us because of you. The LORD your God is indeed God in heaven above and on earth below.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 12, 'Now then, since I have dealt kindly with you, swear to me by the LORD that you in turn will deal kindly with my family. Give me a sign of good faith', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 13, 'that you will spare my father and mother, my brothers and sisters, and all who belong to them, and deliver our lives from death."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 14, 'The men said to her, "Our life for yours! If you do not tell this business of ours, then we will deal kindly and faithfully with you when the LORD gives us the land."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 15, 'Then she let them down by a rope through the window, for her house was on the outer side of the city wall and she resided within the wall itself.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 16, 'She said to them, "Go toward the hill country, so that the pursuers may not come upon you. Hide yourselves there three days, until the pursuers have returned; then afterward you may go your way."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 17, 'The men said to her, "We will be released from this oath that you have made us swear to you', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 18, 'if we invade the land and you do not tie this crimson cord in the window through which you let us down, and you do not gather into your house your father and mother, your brothers, and all your family.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 19, 'If any of you go out of the doors of your house into the street, they shall be responsible for their own death, and we shall be innocent; but if a hand is laid upon any who are with you in the house, we shall bear the responsibility for their death.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 20, 'But if you tell this business of ours, then we shall be released from this oath that you made us swear to you."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 21, 'She said, "According to your words, so be it." She sent them away and they departed. Then she tied the crimson cord in the window.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 22, 'They departed and went into the hill country and stayed there three days, until the pursuers returned. The pursuers had searched all along the way and found nothing.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 23, 'Then the two men came down again from the hill country. They crossed over, came to Joshua son of Nun, and told him all that had happened to them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 2, 24, 'They said to Joshua, "Truly the LORD has given all the land into our hands; moreover all the inhabitants of the land melt in fear before us."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 3, 1, 'Early in the morning Joshua rose and set out from Shittim with all the Israelites, and they came to the Jordan. They camped there before crossing over.', 'en', 'NRSV-CE', 'Israel Crosses the Jordan'),
(6, 'Yos', 'Joshua', 3, 2, 'At the end of three days the officers went through the camp', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 3, 'and commanded the people, "When you see the ark of the covenant of the LORD your God being carried by the levitical priests, then you shall set out from your place. Follow it,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 4, 'so that you may know the way you should go, for you have not passed this way before. Yet there shall be a space between you and it, a distance of about two thousand cubits; do not come any nearer to it."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 5, 'Then Joshua said to the people, "Sanctify yourselves; for tomorrow the LORD will do wonders among you."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 6, 'To the priests Joshua said, "Take up the ark of the covenant, and pass on in front of the people." So they took up the ark of the covenant and went in front of the people.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 7, 'The LORD said to Joshua, "This day I will begin to exalt you in the sight of all Israel, so that they may know that I will be with you as I was with Moses.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 8, 'You are the one who shall command the priests who bear the ark of the covenant, "When you come to the edge of the waters of the Jordan, you shall stand still in the Jordan.""', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 9, 'Joshua then said to the Israelites, "Draw near and hear the words of the LORD your God."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 10, 'Joshua said, "By this you shall know that among you is the living God who without fail will drive out from before you the Canaanites, Hittites, Hivites, Perizzites, Girgashites, Amorites, and Jebusites:', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 11, 'the ark of the covenant of the Lord of all the earth is going to pass before you into the Jordan.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 12, 'So now select twelve men from the tribes of Israel, one from each tribe.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 13, 'When the soles of the feet of the priests who bear the ark of the LORD, the Lord of all the earth, rest in the waters of the Jordan, the waters of the Jordan flowing from above shall be cut off; they shall stand in a single heap."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 14, 'When the people set out from their tents to cross over the Jordan, the priests bearing the ark of the covenant were in front of the people.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 15, 'Now the Jordan overflows all its banks throughout the time of harvest. So when those who bore the ark had come to the Jordan, and the feet of the priests bearing the ark were dipped in the edge of the water,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 16, 'the waters flowing from above stood still, rising up in a single heap far off at Adam, the city that is beside Zarethan, while those flowing toward the sea of the Arabah, the Dead Sea, were wholly cut off. Then the people crossed over opposite Jericho.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 3, 17, 'While all Israel were crossing over on dry ground, the priests who bore the ark of the covenant of the LORD stood on dry ground in the middle of the Jordan, until the entire nation finished crossing over the Jordan.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 4, 1, 'When the entire nation had finished crossing over the Jordan, the LORD said to Joshua:', 'en', 'NRSV-CE', 'Twelve Stones Set Up at Gilgal'),
(6, 'Yos', 'Joshua', 4, 2, '"Select twelve men from the people, one from each tribe,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 3, 'and command them, "Take twelve stones from here out of the middle of the Jordan, from the place where the priests" feet stood, carry them over with you, and lay them down in the place where you camp tonight.""', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 4, 'Then Joshua summoned the twelve men from the Israelites, whom he had appointed, one from each tribe.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 5, 'Joshua said to them, "Pass on before the ark of the LORD your God into the middle of the Jordan, and each of you take up a stone on his shoulder, one for each of the tribes of the Israelites,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 6, 'so that this may be a sign among you. When your children ask in time to come, "What do those stones mean to you?"', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 7, 'then you shall tell them that the waters of the Jordan were cut off in front of the ark of the covenant of the LORD. When it crossed over the Jordan, the waters of the Jordan were cut off. So these stones shall be to the Israelites a memorial forever."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 8, 'The Israelites did as Joshua commanded. They took up twelve stones out of the middle of the Jordan, according to the number of the tribes of the Israelites, as the LORD told Joshua, carried them over with them to the place where they camped, and laid them down there.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 9, '(Joshua set up twelve stones in the middle of the Jordan, in the place where the feet of the priests bearing the ark of the covenant had stood; and they are there to this day.)', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 10, 'The priests who bore the ark remained standing in the middle of the Jordan, until everything was finished that the LORD commanded Joshua to tell the people, according to all that Moses had commanded Joshua. The people crossed over in haste.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 11, 'As soon as all the people had finished crossing over, the ark of the LORD, and the priests, crossed over in front of the people.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 12, 'The Reubenites, the Gadites, and the half-tribe of Manasseh crossed over armed before the Israelites, as Moses had ordered them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 13, 'About forty thousand armed for war crossed over before the LORD to the plains of Jericho for battle.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 14, 'On that day the LORD exalted Joshua in the sight of all Israel; and they stood in awe of him, as they had stood in awe of Moses, all the days of his life.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 15, 'The LORD said to Joshua,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 16, '"Command the priests who bear the ark of the covenant, to come up out of the Jordan."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 17, 'Joshua therefore commanded the priests, "Come up out of the Jordan."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 18, 'When the priests bearing the ark of the covenant of the LORD came up from the middle of the Jordan, and the soles of the priests" feet touched dry ground, the waters of the Jordan returned to their place and overflowed all its banks, as before.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 19, 'The people came up out of the Jordan on the tenth day of the first month, and they camped in Gilgal on the east border of Jericho.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 20, 'Those twelve stones, which they had taken out of the Jordan, Joshua set up in Gilgal,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 21, 'saying to the Israelites, "When your children ask their parents in time to come, "What do these stones mean?"', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 22, 'then you shall let your children know, "Israel crossed over the Jordan here on dry ground."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 23, 'For the LORD your God dried up the waters of the Jordan for you until you crossed over, as the LORD your God did to the Red Sea, which he dried up for us until we crossed over,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 4, 24, 'so that all the peoples of the earth may know that the hand of the LORD is mighty, and so that you may fear the LORD your God forever."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 5, 1, 'When all the kings of the Amorites beyond the Jordan to the west, and all the kings of the Canaanites by the sea, heard that the LORD had dried up the waters of the Jordan for the Israelites until they had crossed over, their hearts melted, and there was no longer any spirit in them, because of the Israelites.', 'en', 'NRSV-CE', 'The New Generation Circumcised'),
(6, 'Yos', 'Joshua', 5, 2, 'At that time the LORD said to Joshua, "Make flint knives and circumcise the Israelites a second time."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 3, 'So Joshua made flint knives, and circumcised the Israelites at Gibeath-haaraloth.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 4, 'This is the reason why Joshua circumcised them: all the males of the people who came out of Egypt, all the warriors, had died during the journey through the wilderness after they had come out of Egypt.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 5, 'Although all the people who came out had been circumcised, yet all the people born on the journey through the wilderness after they had come out of Egypt had not been circumcised.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 6, 'For the Israelites traveled forty years in the wilderness, until all the nation, the warriors who came out of Egypt, perished, not having listened to the voice of the LORD. To them the LORD swore that he would not let them see the land that he had sworn to their ancestors to give us, a land flowing with milk and honey.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 7, 'So it was their children, whom he raised up in their place, that Joshua circumcised; for they were uncircumcised, because they had not been circumcised on the way.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 8, 'When the circumcising of all the nation was done, they remained in their places in the camp until they were healed.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 9, 'The LORD said to Joshua, "Today I have rolled away from you the disgrace of Egypt." And so that place is called Gilgal to this day.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 10, 'While the Israelites were camped in Gilgal they kept the passover in the evening on the fourteenth day of the month in the plains of Jericho.', 'en', 'NRSV-CE', 'The Passover at Gilgal'),
(6, 'Yos', 'Joshua', 5, 11, 'On the day after the passover, on that very day, they ate the produce of the land, unleavened cakes and parched grain.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 12, 'The manna ceased on the day they ate the produce of the land, and the Israelites no longer had manna; they ate the crops of the land of Canaan that year.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 13, 'Once when Joshua was by Jericho, he looked up and saw a man standing before him with a drawn sword in his hand. Joshua went to him and said to him, "Are you one of us, or one of our adversaries?"', 'en', 'NRSV-CE', 'Joshua"s Vision'),
(6, 'Yos', 'Joshua', 5, 14, 'He replied, "Neither; but as commander of the army of the LORD I have now come." And Joshua fell on his face to the earth and worshiped, and he said to him, "What do you command your servant, my lord?"', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 5, 15, 'The commander of the army of the LORD said to Joshua, "Remove the sandals from your feet, for the place where you stand is holy." And Joshua did so.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 6, 1, 'Now Jericho was shut up inside and out because of the Israelites; no one came out and no one went in.', 'en', 'NRSV-CE', 'Jericho Taken and Destroyed'),
(6, 'Yos', 'Joshua', 6, 2, 'The LORD said to Joshua, "See, I have handed Jericho over to you, along with its king and soldiers.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 3, 'You shall march around the city, all the warriors circling the city once. Thus you shall do for six days,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 4, 'with seven priests bearing seven trumpets of rams" horns before the ark. On the seventh day you shall march around the city seven times, the priests blowing the trumpets.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 5, 'When they make a long blast with the ram"s horn, as soon as you hear the sound of the trumpet, then all the people shall shout with a great shout; and the wall of the city will fall down flat, and all the people shall charge straight ahead."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 6, 'So Joshua son of Nun summoned the priests and said to them, "Take up the ark of the covenant, and have seven priests carry seven trumpets of rams" horns in front of the ark of the LORD."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 7, 'To the people he said, "Go forward and march around the city; have the armed men pass on before the ark of the LORD."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 8, 'As Joshua had commanded the people, the seven priests carrying the seven trumpets of rams" horns before the LORD went forward, blowing the trumpets, with the ark of the covenant of the LORD following them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 9, 'And the armed men went before the priests who blew the trumpets; the rear guard came after the ark, while the trumpets blew continually.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 10, 'To the people Joshua gave this command: "You shall not shout or let your voice be heard, nor shall you utter a word, until the day I tell you to shout. Then you shall shout."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 11, 'So the ark of the LORD went around the city, circling it once; and they came into the camp, and spent the night in the camp.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 12, 'Then Joshua rose early in the morning, and the priests took up the ark of the LORD.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 13, 'The seven priests carrying the seven trumpets of rams" horns before the ark of the LORD passed on, blowing the trumpets continually. The armed men went before them, and the rear guard came after the ark of the LORD, while the trumpets blew continually.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 14, 'On the second day they marched around the city once and then returned to the camp. They did this for six days.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 15, 'On the seventh day they rose early, at dawn, and marched around the city in the same manner seven times. It was only on that day that they marched around the city seven times.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 16, 'And at the seventh time, when the priests had blown the trumpets, Joshua said to the people, "Shout! For the LORD has given you the city.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 17, 'The city and all that is in it shall be devoted to the LORD for destruction. Only Rahab the prostitute and all who are with her in her house shall live because she hid the messengers we sent.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 18, 'As for you, keep away from the things devoted to destruction, so as not to covet and take any of the devoted things and make the camp of Israel an object for destruction, bringing trouble upon it.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 19, 'But all silver and gold, and vessels of bronze and iron, are sacred to the LORD; they shall go into the treasury of the LORD."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 20, 'So the people shouted, and the trumpets were blown. As soon as the people heard the sound of the trumpets, they raised a great shout, and the wall fell down flat; so the people charged straight ahead into the city and captured it.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 21, 'Then they devoted to destruction by the edge of the sword all in the city, both men and women, young and old, oxen, sheep, and donkeys.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 22, 'Joshua said to the two men who had spied out the land, "Go into the prostitute"s house, and bring the woman out of it and all who belong to her, as you swore to her."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 23, 'So the young men who had been spies went in and brought Rahab out, along with her father, her mother, her brothers, and all who belonged to her--they brought all her kindred out--and set them outside the camp of Israel.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 24, 'They burned down the city, and everything in it; only the silver and gold, and the vessels of bronze and iron, they put into the treasury of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 25, 'But Rahab the prostitute, with her family and all who belonged to her, Joshua spared. Her family has lived in Israel ever since. For she hid the messengers whom Joshua sent to spy out Jericho.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 6, 26, 'Joshua then pronounced this oath, saying,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 7, 1, 'But the Israelites broke faith in regard to the devoted things: Achan son of Carmi son of Zabdi son of Zerah, of the tribe of Judah, took some of the devoted things; and the anger of the LORD burned against the Israelites.', 'en', 'NRSV-CE', 'The Sin of Achan and Its Punishment'),
(6, 'Yos', 'Joshua', 7, 2, 'Joshua sent men from Jericho to Ai, which is near Beth-aven, east of Bethel, and said to them, "Go up and spy out the land." And the men went up and spied out Ai.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 3, 'Then they returned to Joshua and said to him, "Not all the people need go up; about two or three thousand men should go up and attack Ai. Since they are so few, do not make the whole people toil up there."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 4, 'So about three thousand of the people went up there; and they fled before the men of Ai.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 5, 'The men of Ai killed about thirty-six of them, chasing them from outside the gate as far as Shebarim and killing them on the slope. The hearts of the people melted and turned to water.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 6, 'Then Joshua tore his clothes, and fell to the ground on his face before the ark of the LORD until the evening, he and the elders of Israel; and they put dust on their heads.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 7, 'Joshua said, "Ah, Lord God! Why have you brought this people across the Jordan at all, to hand us over to the Amorites so as to destroy us? Would that we had been content to settle beyond the Jordan!', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 8, 'O Lord, what can I say, now that Israel has turned their backs to their enemies!', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 9, 'The Canaanites and all the inhabitants of the land will hear of it, and surround us, and cut off our name from the earth. Then what will you do for your great name?"', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 10, 'The LORD said to Joshua, "Stand up! Why have you fallen upon your face?', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 11, 'Israel has sinned; they have transgressed my covenant that I imposed on them. They have taken some of the devoted things; they have stolen, they have acted deceitfully, and they have put them among their own belongings.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 12, 'Therefore the Israelites are unable to stand before their enemies; they turn their backs to their enemies, because they have become a thing devoted for destruction themselves. I will be with you no more, unless you destroy the devoted things from among you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 13, 'Proceed to sanctify the people, and say, "Sanctify yourselves for tomorrow; for thus says the LORD, the God of Israel, "There are devoted things among you, O Israel; you will be unable to stand before your enemies until you take away the devoted things from among you."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 14, 'In the morning therefore you shall come forward tribe by tribe. The tribe that the LORD takes shall come near by clans, the clan that the LORD takes shall come near by households, and the household that the LORD takes shall come near one by one.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 15, 'And the one who is taken as having the devoted things shall be burned with fire, together with all that he has, for having transgressed the covenant of the LORD, and for having done an outrageous thing in Israel.""', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 16, 'So Joshua rose early in the morning, and brought Israel near tribe by tribe, and the tribe of Judah was taken.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 17, 'He brought near the clans of Judah, and the clan of the Zerahites was taken; and he brought near the clan of the Zerahites, family by family, and Zabdi was taken.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 18, 'And he brought near his household one by one, and Achan son of Carmi son of Zabdi son of Zerah, of the tribe of Judah, was taken.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 19, 'Then Joshua said to Achan, "My son, give glory to the LORD God of Israel and make confession to him. Tell me now what you have done; do not hide it from me."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 20, 'And Achan answered Joshua, "It is true; I am the one who sinned against the LORD God of Israel. This is what I did:', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 21, 'when I saw among the spoil a beautiful mantle from Shinar, and two hundred shekels of silver, and a bar of gold weighing fifty shekels, then I coveted them and took them. They now lie hidden in the ground inside my tent, with the silver underneath."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 22, 'So Joshua sent messengers, and they ran to the tent; and there it was, hidden in his tent with the silver underneath.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 23, 'They took them out of the tent and brought them to Joshua and all the Israelites; and they spread them out before the LORD.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 24, 'Then Joshua and all Israel with him took Achan son of Zerah, with the silver, the mantle, and the bar of gold, with his sons and daughters, with his oxen, donkeys, and sheep, and his tent and all that he had; and they brought them up to the Valley of Achor.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 25, 'Joshua said, "Why did you bring trouble on us? The LORD is bringing trouble on you today." And all Israel stoned him to death; they burned them with fire, cast stones on them,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 7, 26, 'and raised over him a great heap of stones that remains to this day. Then the LORD turned from his burning anger. Therefore that place to this day is called the Valley of Achor.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 8, 1, 'Then the LORD said to Joshua, "Do not fear or be dismayed; take all the fighting men with you, and go up now to Ai. See, I have handed over to you the king of Ai with his people, his city, and his land.', 'en', 'NRSV-CE', 'Ai Captured by a Stratagem and Destroyed'),
(6, 'Yos', 'Joshua', 8, 2, 'You shall do to Ai and its king as you did to Jericho and its king; only its spoil and its livestock you may take as booty for yourselves. Set an ambush against the city, behind it."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 3, 'So Joshua and all the fighting men set out to go up against Ai. Joshua chose thirty thousand warriors and sent them out by night', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 4, 'with the command, "You shall lie in ambush against the city, behind it; do not go very far from the city, but all of you stay alert.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 5, 'I and all the people who are with me will approach the city. When they come out against us, as before, we shall flee from them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 6, 'They will come out after us until we have drawn them away from the city; for they will say, "They are fleeing from us, as before." While we flee from them,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 7, 'you shall rise up from the ambush and seize the city; for the LORD your God will give it into your hand.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 8, 'And when you have taken the city, you shall set the city on fire, doing as the LORD has ordered; see, I have commanded you."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 9, 'So Joshua sent them out; and they went to the place of ambush, and lay between Bethel and Ai, to the west of Ai; but Joshua spent that night in the camp.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 10, 'In the morning Joshua rose early and mustered the people, and went up, with the elders of Israel, before the people to Ai.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 11, 'All the fighting men who were with him went up, and drew near before the city, and camped on the north side of Ai, with a ravine between them and Ai.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 12, 'Taking about five thousand men, he set them in ambush between Bethel and Ai, to the west of the city.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 13, 'So they stationed the forces, the main encampment that was north of the city and its rear guard west of the city. But Joshua spent that night in the valley.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 14, 'When the king of Ai saw this, he and all his people, the inhabitants of the city, hurried out early in the morning to the meeting place facing the Arabah to meet Israel in battle; but he did not know that there was an ambush against him behind the city.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 15, 'And Joshua and all Israel made a pretense of being beaten before them, and fled in the direction of the wilderness.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 16, 'So all the people who were in the city were called together to pursue them, and as they pursued Joshua they were drawn away from the city.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 17, 'There was not a man left in Ai or Bethel who did not go out after Israel; they left the city open, and pursued Israel.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 18, 'Then the LORD said to Joshua, "Stretch out the sword that is in your hand toward Ai; for I will give it into your hand." And Joshua stretched out the sword that was in his hand toward the city.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 19, 'As soon as he stretched out his hand, the troops in ambush rose quickly out of their place and rushed forward. They entered the city, took it, and at once set the city on fire.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 20, 'So when the men of Ai looked back, the smoke of the city was rising to the sky. They had no power to flee this way or that, for the people who fled to the wilderness turned back against the pursuers.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 21, 'When Joshua and all Israel saw that the ambush had taken the city and that the smoke of the city was rising, then they turned back and struck down the men of Ai.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 22, 'And the others came out from the city against them; so they were surrounded by Israelites, some on one side, and some on the other; and Israel struck them down until no one was left who survived or escaped.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 23, 'But the king of Ai was taken alive and brought to Joshua.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 24, 'When Israel had finished slaughtering all the inhabitants of Ai in the open wilderness where they pursued them, and when all of them to the very last had fallen by the edge of the sword, all Israel returned to Ai, and attacked it with the edge of the sword.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 25, 'The total of those who fell that day, both men and women, was twelve thousand--all the people of Ai.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 26, 'For Joshua did not draw back his hand, with which he stretched out the sword, until he had utterly destroyed all the inhabitants of Ai.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 27, 'Only the livestock and the spoil of that city Israel took as their booty, according to the word of the LORD that he had issued to Joshua.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 28, 'So Joshua burned Ai, and made it forever a heap of ruins, as it is to this day.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 29, 'And he hanged the king of Ai on a tree until evening; and at sunset Joshua commanded, and they took his body down from the tree, threw it down at the entrance of the gate of the city, and raised over it a great heap of stones, which stands there to this day.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 30, 'Then Joshua built on Mount Ebal an altar to the LORD, the God of Israel,', 'en', 'NRSV-CE', 'Joshua Renews the Covenant'),
(6, 'Yos', 'Joshua', 8, 31, 'just as Moses the servant of the LORD had commanded the Israelites, as it is written in the book of the law of Moses, "an altar of unhewn stones, on which no iron tool has been used"; and they offered on it burnt offerings to the LORD, and sacrificed offerings of well-being.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 32, 'And there, in the presence of the Israelites, Joshua wrote on the stones a copy of the law of Moses, which he had written.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 33, 'All Israel, alien as well as citizen, with their elders and officers and their judges, stood on opposite sides of the ark in front of the levitical priests who carried the ark of the covenant of the LORD, half of them in front of Mount Gerizim and half of them in front of Mount Ebal, as Moses the servant of the LORD had commanded at the first, that they should bless the people of Israel.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 34, 'And afterward he read all the words of the law, blessings and curses, according to all that is written in the book of the law.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 8, 35, 'There was not a word of all that Moses commanded that Joshua did not read before all the assembly of Israel, and the women, and the little ones, and the aliens who resided among them.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 9, 1, 'Now when all the kings who were beyond the Jordan in the hill country and in the lowland all along the coast of the Great Sea toward Lebanon--the Hittites, the Amorites, the Canaanites, the Perizzites, the Hivites, and the Jebusites--heard of this,', 'en', 'NRSV-CE', 'The Gibeonites Save Themselves by Trickery'),
(6, 'Yos', 'Joshua', 9, 2, 'they gathered together with one accord to fight Joshua and Israel.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 3, 'But when the inhabitants of Gibeon heard what Joshua had done to Jericho and to Ai,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 4, 'they on their part acted with cunning: they went and prepared provisions, and took worn-out sacks for their donkeys, and wineskins, worn-out and torn and mended,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 5, 'with worn-out, patched sandals on their feet, and worn-out clothes; and all their provisions were dry and moldy.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 6, 'They went to Joshua in the camp at Gilgal, and said to him and to the Israelites, "We have come from a far country; so now make a treaty with us."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 7, 'But the Israelites said to the Hivites, "Perhaps you live among us; then how can we make a treaty with you?"', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 8, 'They said to Joshua, "We are your servants." And Joshua said to them, "Who are you? And where do you come from?"', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 9, 'They said to him, "Your servants have come from a very far country, because of the name of the LORD your God; for we have heard a report of him, of all that he did in Egypt,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 10, 'and of all that he did to the two kings of the Amorites who were beyond the Jordan, King Sihon of Heshbon, and King Og of Bashan who lived in Ashtaroth.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 11, 'So our elders and all the inhabitants of our country said to us, "Take provisions in your hand for the journey; go to meet them, and say to them, "We are your servants; come now, make a treaty with us.""', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 12, 'Here is our bread; it was still warm when we took it from our houses as our food for the journey, on the day we set out to come to you, but now, see, it is dry and moldy;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 13, 'these wineskins were new when we filled them, and see, they are burst; and these garments and sandals of ours are worn out from the very long journey."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 14, 'So the leaders partook of their provisions, and did not ask direction from the LORD.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 15, 'And Joshua made peace with them, guaranteeing their lives by a treaty; and the leaders of the congregation swore an oath to them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 16, 'But when three days had passed after they had made a treaty with them, they heard that they were their neighbors and were living among them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 17, 'So the Israelites set out and reached their cities on the third day. Now their cities were Gibeon, Chephirah, Beeroth, and Kiriath-jearim.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 18, 'But the Israelites did not attack them, because the leaders of the congregation had sworn to them by the LORD, the God of Israel. Then all the congregation murmured against the leaders.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 19, 'But all the leaders said to all the congregation, "We have sworn to them by the LORD, the God of Israel, and now we must not touch them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 20, 'This is what we will do to them: We will let them live, so that wrath may not come upon us, because of the oath that we swore to them."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 21, 'The leaders said to them, "Let them live." So they became hewers of wood and drawers of water for all the congregation, as the leaders had decided concerning them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 22, 'Joshua summoned them, and said to them, "Why did you deceive us, saying, "We are very far from you," while in fact you are living among us?', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 23, 'Now therefore you are cursed, and some of you shall always be slaves, hewers of wood and drawers of water for the house of my God."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 24, 'They answered Joshua, "Because it was told to your servants for a certainty that the LORD your God had commanded his servant Moses to give you all the land, and to destroy all the inhabitants of the land before you; so we were in great fear for our lives because of you, and did this thing.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 25, 'And now we are in your hand: do as it seems good and right in your sight to do to us."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 26, 'This is what he did for them: he saved them from the Israelites; and they did not kill them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 9, 27, 'But on that day Joshua made them hewers of wood and drawers of water for the congregation and for the altar of the LORD, to continue to this day, in the place that he should choose.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 10, 1, 'When King Adoni-zedek of Jerusalem heard how Joshua had taken Ai, and had utterly destroyed it, doing to Ai and its king as he had done to Jericho and its king, and how the inhabitants of Gibeon had made peace with Israel and were among them,', 'en', 'NRSV-CE', 'The Sun Stands Still'),
(6, 'Yos', 'Joshua', 10, 2, 'he became greatly frightened, because Gibeon was a large city, like one of the royal cities, and was larger than Ai, and all its men were warriors.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 3, 'So King Adoni-zedek of Jerusalem sent a message to King Hoham of Hebron, to King Piram of Jarmuth, to King Japhia of Lachish, and to King Debir of Eglon, saying,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 4, '"Come up and help me, and let us attack Gibeon; for it has made peace with Joshua and with the Israelites."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 5, 'Then the five kings of the Amorites--the king of Jerusalem, the king of Hebron, the king of Jarmuth, the king of Lachish, and the king of Eglon--gathered their forces, and went up with all their armies and camped against Gibeon, and made war against it.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 6, 'And the Gibeonites sent to Joshua at the camp in Gilgal, saying, "Do not abandon your servants; come up to us quickly, and save us, and help us; for all the kings of the Amorites who live in the hill country are gathered against us."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 7, 'So Joshua went up from Gilgal, he and all the fighting force with him, all the mighty warriors.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 8, 'The LORD said to Joshua, "Do not fear them, for I have handed them over to you; not one of them shall stand before you."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 9, 'So Joshua came upon them suddenly, having marched up all night from Gilgal.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 10, 'And the LORD threw them into a panic before Israel, who inflicted a great slaughter on them at Gibeon, chased them by the way of the ascent of Beth-horon, and struck them down as far as Azekah and Makkedah.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 11, 'As they fled before Israel, while they were going down the slope of Beth-horon, the LORD threw down huge stones from heaven on them as far as Azekah, and they died; there were more who died because of the hailstones than the Israelites killed with the sword.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 10, 12, 'On the day when the LORD gave the Amorites over to the Israelites, Joshua spoke to the LORD; and he said in the sight of Israel,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 11, 1, 'When King Jabin of Hazor heard of this, he sent to King Jobab of Madon, to the king of Shimron, to the king of Achshaph,', 'en', 'NRSV-CE', 'The United Kings of Northern Canaan Defeated'),
(6, 'Yos', 'Joshua', 11, 2, 'and to the kings who were in the northern hill country, and in the Arabah south of Chinneroth, and in the lowland, and in Naphoth-dor on the west,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 3, 'to the Canaanites in the east and the west, the Amorites, the Hittites, the Perizzites, and the Jebusites in the hill country, and the Hivites under Hermon in the land of Mizpah.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 4, 'They came out, with all their troops, a great army, in number like the sand on the seashore, with very many horses and chariots.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 5, 'All these kings joined their forces, and came and camped together at the waters of Merom, to fight with Israel.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 6, 'And the LORD said to Joshua, "Do not be afraid of them, for tomorrow at this time I will hand over all of them, slain, to Israel; you shall hamstring their horses, and burn their chariots with fire."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 7, 'So Joshua came suddenly upon them with all his fighting force, by the waters of Merom, and fell upon them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 8, 'And the LORD handed them over to Israel, who attacked them and chased them as far as Great Sidon and Misrephoth-maim, and eastward as far as the valley of Mizpeh. They struck them down, until they had left no one remaining.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 9, 'And Joshua did to them as the LORD commanded him; he hamstrung their horses, and burned their chariots with fire.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 10, 'Joshua turned back at that time, and took Hazor, and struck its king down with the sword. Before that time Hazor was the head of all those kingdoms.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 11, 'And they put to the sword all who were in it, utterly destroying them; there was no one left who breathed, and he burned Hazor with fire.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 12, 'And all the towns of those kings, and all their kings, Joshua took, and struck them with the edge of the sword, utterly destroying them, as Moses the servant of the LORD had commanded.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 13, 'But Israel burned none of the towns that stood on mounds except Hazor, which Joshua did burn.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 14, 'All the spoil of these towns, and the livestock, the Israelites took for their booty; but all the people they struck down with the edge of the sword, until they had destroyed them, and they did not leave any who breathed.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 15, 'As the LORD had commanded his servant Moses, so Moses commanded Joshua, and so Joshua did; he left nothing undone of all that the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 16, 'So Joshua took all that land: the hill country and all the Negeb and all the land of Goshen and the lowland and the Arabah and the hill country of Israel and its lowland,', 'en', 'NRSV-CE', 'Summary of Joshua"s Conquests'),
(6, 'Yos', 'Joshua', 11, 17, 'from Mount Halak, which rises toward Seir, as far as Baal-gad in the valley of Lebanon below Mount Hermon. He took all their kings, struck them down, and put them to death.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 18, 'Joshua made war a long time with all those kings.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 19, 'There was not a town that made peace with the Israelites, except the Hivites, the inhabitants of Gibeon; all were taken in battle.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 20, 'For it was the LORD"s doing to harden their hearts so that they would come against Israel in battle, in order that they might be utterly destroyed, and might receive no mercy, but be exterminated, just as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 21, 'At that time Joshua came and wiped out the Anakim from the hill country, from Hebron, from Debir, from Anab, and from all the hill country of Judah, and from all the hill country of Israel; Joshua utterly destroyed them with their towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 22, 'None of the Anakim was left in the land of the Israelites; some remained only in Gaza, in Gath, and in Ashdod.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 11, 23, 'So Joshua took the whole land, according to all that the LORD had spoken to Moses; and Joshua gave it for an inheritance to Israel according to their tribal allotments. And the land had rest from war.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 12, 1, 'Now these are the kings of the land, whom the Israelites defeated, whose land they occupied beyond the Jordan toward the east, from the Wadi Arnon to Mount Hermon, with all the Arabah eastward:', 'en', 'NRSV-CE', 'The Kings Conquered by Moses'),
(6, 'Yos', 'Joshua', 12, 2, 'King Sihon of the Amorites who lived at Heshbon, and ruled from Aroer, which is on the edge of the Wadi Arnon, and from the middle of the valley as far as the river Jabbok, the boundary of the Ammonites, that is, half of Gilead,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 3, 'and the Arabah to the Sea of Chinneroth eastward, and in the direction of Beth-jeshimoth, to the sea of the Arabah, the Dead Sea, southward to the foot of the slopes of Pisgah;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 4, 'and King Og of Bashan, one of the last of the Rephaim, who lived at Ashtaroth and at Edrei', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 5, 'and ruled over Mount Hermon and Salecah and all Bashan to the boundary of the Geshurites and the Maacathites, and over half of Gilead to the boundary of King Sihon of Heshbon.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 6, 'Moses, the servant of the LORD, and the Israelites defeated them; and Moses the servant of the LORD gave their land for a possession to the Reubenites and the Gadites and the half-tribe of Manasseh.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 7, 'The following are the kings of the land whom Joshua and the Israelites defeated on the west side of the Jordan, from Baal-gad in the valley of Lebanon to Mount Halak, that rises toward Seir (and Joshua gave their land to the tribes of Israel as a possession according to their allotments,', 'en', 'NRSV-CE', 'The Kings Conquered by Joshua'),
(6, 'Yos', 'Joshua', 12, 8, 'in the hill country, in the lowland, in the Arabah, in the slopes, in the wilderness, and in the Negeb, the land of the Hittites, Amorites, Canaanites, Perizzites, Hivites, and Jebusites):', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 9, 'the king of Jericho, one;the king of Ai, which is next to Bethel, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 10, 'the king of Jerusalem, one;the king of Hebron, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 11, 'the king of Jarmuth, one;the king of Lachish, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 12, 'the king of Eglon, one;the king of Gezer, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 13, 'the king of Debir, one;the king of Geder, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 14, 'the king of Hormah, one;the king of Arad, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 15, 'the king of Libnah, one;the king of Adullam, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 16, 'the king of Makkedah, one;the king of Bethel, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 17, 'the king of Tappuah, one;the king of Hepher, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 18, 'the king of Aphek, one;the king of Lasharon, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 19, 'the king of Madon, one;the king of Hazor, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 20, 'the king of Shimron-meron, one;the king of Achshaph, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 21, 'the king of Taanach, one;the king of Megiddo, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 22, 'the king of Kedesh, one;the king of Jokneam in Carmel, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 23, 'the king of Dor in Naphath-dor, one;the king of Goiim in Galilee,, one;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 12, 24, 'the king of Tirzah, one; thirty-one kings in all.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 13, 1, 'Now Joshua was old and advanced in years; and the LORD said to him, "You are old and advanced in years, and very much of the land still remains to be possessed.', 'en', 'NRSV-CE', 'The Parts of Canaan Still Unconquered'),
(6, 'Yos', 'Joshua', 13, 2, 'This is the land that still remains: all the regions of the Philistines, and all those of the Geshurites', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 3, '(from the Shihor, which is east of Egypt, northward to the boundary of Ekron, it is reckoned as Canaanite; there are five rulers of the Philistines, those of Gaza, Ashdod, Ashkelon, Gath, and Ekron), and those of the Avvim', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 4, 'in the south; all the land of the Canaanites, and Mearah that belongs to the Sidonians, to Aphek, to the boundary of the Amorites,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 5, 'and the land of the Gebalites, and all Lebanon, toward the east, from Baal-gad below Mount Hermon to Lebo-hamath,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 6, 'all the inhabitants of the hill country from Lebanon to Misrephoth-maim, even all the Sidonians. I will myself drive them out from before the Israelites; only allot the land to Israel for an inheritance, as I have commanded you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 7, 'Now therefore divide this land for an inheritance to the nine tribes and the half-tribe of Manasseh."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 8, 'With the other half-tribe of Manasseh the Reubenites and the Gadites received their inheritance, which Moses gave them, beyond the Jordan eastward, as Moses the servant of the LORD gave them:', 'en', 'NRSV-CE', 'The Territory East of the Jordan'),
(6, 'Yos', 'Joshua', 13, 9, 'from Aroer, which is on the edge of the Wadi Arnon, and the town that is in the middle of the valley, and all the tableland from Medeba as far as Dibon;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 10, 'and all the cities of King Sihon of the Amorites, who reigned in Heshbon, as far as the boundary of the Ammonites;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 11, 'and Gilead, and the region of the Geshurites and Maacathites, and all Mount Hermon, and all Bashan to Salecah;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 12, 'all the kingdom of Og in Bashan, who reigned in Ashtaroth and in Edrei (he alone was left of the survivors of the Rephaim); these Moses had defeated and driven out.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 13, 'Yet the Israelites did not drive out the Geshurites or the Maacathites; but Geshur and Maacath live within Israel to this day.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 14, 'To the tribe of Levi alone Moses gave no inheritance; the offerings by fire to the LORD God of Israel are their inheritance, as he said to them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 15, 'Moses gave an inheritance to the tribe of the Reubenites according to their clans.', 'en', 'NRSV-CE', 'The Territory of Reuben'),
(6, 'Yos', 'Joshua', 13, 16, 'Their territory was from Aroer, which is on the edge of the Wadi Arnon, and the town that is in the middle of the valley, and all the tableland by Medeba;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 17, 'with Heshbon, and all its towns that are in the tableland; Dibon, and Bamoth-baal, and Beth-baal-meon,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 18, 'and Jahaz, and Kedemoth, and Mephaath,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 19, 'and Kiriathaim, and Sibmah, and Zereth-shahar on the hill of the valley,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 20, 'and Beth-peor, and the slopes of Pisgah, and Beth-jeshimoth,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 21, 'that is, all the towns of the tableland, and all the kingdom of King Sihon of the Amorites, who reigned in Heshbon, whom Moses defeated with the leaders of Midian, Evi and Rekem and Zur and Hur and Reba, as princes of Sihon, who lived in the land.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 22, 'Along with the rest of those they put to death, the Israelites also put to the sword Balaam son of Beor, who practiced divination.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 23, 'And the border of the Reubenites was the Jordan and its banks. This was the inheritance of the Reubenites according to their families with their towns and villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 24, 'Moses gave an inheritance also to the tribe of the Gadites, according to their families.', 'en', 'NRSV-CE', 'The Territory of Gad'),
(6, 'Yos', 'Joshua', 13, 25, 'Their territory was Jazer, and all the towns of Gilead, and half the land of the Ammonites, to Aroer, which is east of Rabbah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 26, 'and from Heshbon to Ramath-mizpeh and Betonim, and from Mahanaim to the territory of Debir,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 27, 'and in the valley Beth-haram, Beth-nimrah, Succoth, and Zaphon, the rest of the kingdom of King Sihon of Heshbon, the Jordan and its banks, as far as the lower end of the Sea of Chinnereth, eastward beyond the Jordan.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 28, 'This is the inheritance of the Gadites according to their clans, with their towns and villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 29, 'Moses gave an inheritance to the half-tribe of Manasseh; it was allotted to the half-tribe of the Manassites according to their families.', 'en', 'NRSV-CE', 'The Territory of the Half-Tribe of Manasseh (East)'),
(6, 'Yos', 'Joshua', 13, 30, 'Their territory extended from Mahanaim, through all Bashan, the whole kingdom of King Og of Bashan, and all the settlements of Jair, which are in Bashan, sixty towns,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 31, 'and half of Gilead, and Ashtaroth, and Edrei, the towns of the kingdom of Og in Bashan; these were allotted to the people of Machir son of Manasseh according to their clans--for half the Machirites.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 32, 'These are the inheritances that Moses distributed in the plains of Moab, beyond the Jordan east of Jericho.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 13, 33, 'But to the tribe of Levi Moses gave no inheritance; the LORD God of Israel is their inheritance, as he said to them.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 14, 1, 'These are the inheritances that the Israelites received in the land of Canaan, which the priest Eleazar, and Joshua son of Nun, and the heads of the families of the tribes of the Israelites distributed to them.', 'en', 'NRSV-CE', 'The Distribution of Territory West of the Jordan'),
(6, 'Yos', 'Joshua', 14, 2, 'Their inheritance was by lot, as the LORD had commanded Moses for the nine and one-half tribes.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 3, 'For Moses had given an inheritance to the two and one-half tribes beyond the Jordan; but to the Levites he gave no inheritance among them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 4, 'For the people of Joseph were two tribes, Manasseh and Ephraim; and no portion was given to the Levites in the land, but only towns to live in, with their pasture lands for their flocks and herds.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 5, 'The Israelites did as the LORD commanded Moses; they allotted the land.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 6, 'Then the people of Judah came to Joshua at Gilgal; and Caleb son of Jephunneh the Kenizzite said to him, "You know what the LORD said to Moses the man of God in Kadesh-barnea concerning you and me.', 'en', 'NRSV-CE', 'Hebron Allotted to Caleb'),
(6, 'Yos', 'Joshua', 14, 7, 'I was forty years old when Moses the servant of the LORD sent me from Kadesh-barnea to spy out the land; and I brought him an honest report.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 8, 'But my companions who went up with me made the heart of the people melt; yet I wholeheartedly followed the LORD my God.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 9, 'And Moses swore on that day, saying, "Surely the land on which your foot has trodden shall be an inheritance for you and your children forever, because you have wholeheartedly followed the LORD my God."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 10, 'And now, as you see, the LORD has kept me alive, as he said, these forty-five years since the time that the LORD spoke this word to Moses, while Israel was journeying through the wilderness; and here I am today, eighty-five years old.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 11, 'I am still as strong today as I was on the day that Moses sent me; my strength now is as my strength was then, for war, and for going and coming.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 12, 'So now give me this hill country of which the LORD spoke on that day; for you heard on that day how the Anakim were there, with great fortified cities; it may be that the LORD will be with me, and I shall drive them out, as the LORD said."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 13, 'Then Joshua blessed him, and gave Hebron to Caleb son of Jephunneh for an inheritance.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 14, 'So Hebron became the inheritance of Caleb son of Jephunneh the Kenizzite to this day, because he wholeheartedly followed the LORD, the God of Israel.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 14, 15, 'Now the name of Hebron formerly was Kiriath-arba; this Arba was the greatest man among the Anakim. And the land had rest from war.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 15, 1, 'The lot for the tribe of the people of Judah according to their families reached southward to the boundary of Edom, to the wilderness of Zin at the farthest south.', 'en', 'NRSV-CE', 'The Territory of Judah'),
(6, 'Yos', 'Joshua', 15, 2, 'And their south boundary ran from the end of the Dead Sea, from the bay that faces southward;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 3, 'it goes out southward of the ascent of Akrabbim, passes along to Zin, and goes up south of Kadesh-barnea, along by Hezron, up to Addar, makes a turn to Karka,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 4, 'passes along to Azmon, goes out by the Wadi of Egypt, and comes to its end at the sea. This shall be your south boundary.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 5, 'And the east boundary is the Dead Sea, to the mouth of the Jordan. And the boundary on the north side runs from the bay of the sea at the mouth of the Jordan;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 6, 'and the boundary goes up to Beth-hoglah, and passes along north of Beth-arabah; and the boundary goes up to the Stone of Bohan, Reuben"s son;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 7, 'and the boundary goes up to Debir from the Valley of Achor, and so northward, turning toward Gilgal, which is opposite the ascent of Adummim, which is on the south side of the valley; and the boundary passes along to the waters of En-shemesh, and ends at En-rogel;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 8, 'then the boundary goes up by the valley of the son of Hinnom at the southern slope of the Jebusites (that is, Jerusalem); and the boundary goes up to the top of the mountain that lies over against the valley of Hinnom, on the west, at the northern end of the valley of Rephaim;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 9, 'then the boundary extends from the top of the mountain to the spring of the Waters of Nephtoah, and from there to the towns of Mount Ephron; then the boundary bends around to Baalah (that is, Kiriath-jearim);', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 10, 'and the boundary circles west of Baalah to Mount Seir, passes along to the northern slope of Mount Jearim (that is, Chesalon), and goes down to Beth-shemesh, and passes along by Timnah;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 11, 'the boundary goes out to the slope of the hill north of Ekron, then the boundary bends around to Shikkeron, and passes along to Mount Baalah, and goes out to Jabneel; then the boundary comes to an end at the sea.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 12, 'And the west boundary was the Mediterranean with its coast. This is the boundary surrounding the people of Judah according to their families.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 13, 'According to the commandment of the LORD to Joshua, he gave to Caleb son of Jephunneh a portion among the people of Judah, Kiriath-arba, that is, Hebron (Arba was the father of Anak).', 'en', 'NRSV-CE', 'Caleb Occupies His Portion'),
(6, 'Yos', 'Joshua', 15, 14, 'And Caleb drove out from there the three sons of Anak: Sheshai, Ahiman, and Talmai, the descendants of Anak.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 15, 'From there he went up against the inhabitants of Debir; now the name of Debir formerly was Kiriath-sepher.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 16, 'And Caleb said, "Whoever attacks Kiriath-sepher and takes it, to him I will give my daughter Achsah as wife."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 17, 'Othniel son of Kenaz, the brother of Caleb, took it; and he gave him his daughter Achsah as wife.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 18, 'When she came to him, she urged him to ask her father for a field. As she dismounted from her donkey, Caleb said to her, "What do you wish?"', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 19, 'She said to him, "Give me a present; since you have set me in the land of the Negeb, give me springs of water as well." So Caleb gave her the upper springs and the lower springs.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 20, 'This is the inheritance of the tribe of the people of Judah according to their families.', 'en', 'NRSV-CE', 'The Towns of Judah'),
(6, 'Yos', 'Joshua', 15, 21, 'The towns belonging to the tribe of the people of Judah in the extreme south, toward the boundary of Edom, were Kabzeel, Eder, Jagur,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 22, 'Kinah, Dimonah, Adadah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 23, 'Kedesh, Hazor, Ithnan,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 24, 'Ziph, Telem, Bealoth,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 25, 'Hazor-hadattah, Kerioth-hezron (that is, Hazor),', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 26, 'Amam, Shema, Moladah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 27, 'Hazar-gaddah, Heshmon, Beth-pelet,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 28, 'Hazar-shual, Beer-sheba, Biziothiah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 29, 'Baalah, Iim, Ezem,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 30, 'Eltolad, Chesil, Hormah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 31, 'Ziklag, Madmannah, Sansannah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 32, 'Lebaoth, Shilhim, Ain, and Rimmon: in all, twenty-nine towns, with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 33, 'And in the lowland, Eshtaol, Zorah, Ashnah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 34, 'Zanoah, En-gannim, Tappuah, Enam,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 35, 'Jarmuth, Adullam, Socoh, Azekah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 36, 'Shaaraim, Adithaim, Gederah, Gederothaim: fourteen towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 37, 'Zenan, Hadashah, Migdal-gad,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 38, 'Dilan, Mizpeh, Jokthe-el,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 39, 'Lachish, Bozkath, Eglon,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 40, 'Cabbon, Lahmam, Chitlish,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 41, 'Gederoth, Beth-dagon, Naamah, and Makkedah: sixteen towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 42, 'Libnah, Ether, Ashan,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 43, 'Iphtah, Ashnah, Nezib,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 44, 'Keilah, Achzib, and Mareshah: nine towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 45, 'Ekron, with its dependencies and its villages;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 46, 'from Ekron to the sea, all that were near Ashdod, with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 47, 'Ashdod, its towns and its villages; Gaza, its towns and its villages; to the Wadi of Egypt, and the Great Sea with its coast.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 48, 'And in the hill country, Shamir, Jattir, Socoh,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 49, 'Dannah, Kiriath-sannah (that is, Debir),', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 50, 'Anab, Eshtemoh, Anim,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 51, 'Goshen, Holon, and Giloh: eleven towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 52, 'Arab, Dumah, Eshan,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 53, 'Janim, Beth-tappuah, Aphekah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 54, 'Humtah, Kiriath-arba (that is, Hebron), and Zior: nine towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 55, 'Maon, Carmel, Ziph, Juttah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 56, 'Jezreel, Jokdeam, Zanoah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 57, 'Kain, Gibeah, and Timnah: ten towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 58, 'Halhul, Beth-zur, Gedor,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 59, 'Maarath, Beth-anoth, and Eltekon: six towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 60, 'Kiriath-baal (that is, Kiriath-jearim) and Rabbah: two towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 61, 'In the wilderness, Beth-arabah, Middin, Secacah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 62, 'Nibshan, the City of Salt, and En-gedi: six towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 15, 63, 'But the people of Judah could not drive out the Jebusites, the inhabitants of Jerusalem; so the Jebusites live with the people of Judah in Jerusalem to this day.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 16, 1, 'The allotment of the Josephites went from the Jordan by Jericho, east of the waters of Jericho, into the wilderness, going up from Jericho into the hill country to Bethel;', 'en', 'NRSV-CE', 'The Territory of Ephraim'),
(6, 'Yos', 'Joshua', 16, 2, 'then going from Bethel to Luz, it passes along to Ataroth, the territory of the Archites;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 16, 3, 'then it goes down westward to the territory of the Japhletites, as far as the territory of Lower Beth-horon, then to Gezer, and it ends at the sea.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 16, 4, 'The Josephites--Manasseh and Ephraim--received their inheritance.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 16, 5, 'The territory of the Ephraimites by their families was as follows: the boundary of their inheritance on the east was Ataroth-addar as far as Upper Beth-horon,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 16, 6, 'and the boundary goes from there to the sea; on the north is Michmethath; then on the east the boundary makes a turn toward Taanath-shiloh, and passes along beyond it on the east to Janoah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 16, 7, 'then it goes down from Janoah to Ataroth and to Naarah, and touches Jericho, ending at the Jordan.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 16, 8, 'From Tappuah the boundary goes westward to the Wadi Kanah, and ends at the sea. Such is the inheritance of the tribe of the Ephraimites by their families,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 16, 9, 'together with the towns that were set apart for the Ephraimites within the inheritance of the Manassites, all those towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 16, 10, 'They did not, however, drive out the Canaanites who lived in Gezer: so the Canaanites have lived within Ephraim to this day but have been made to do forced labor.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 17, 1, 'Then allotment was made to the tribe of Manasseh, for he was the firstborn of Joseph. To Machir the firstborn of Manasseh, the father of Gilead, were allotted Gilead and Bashan, because he was a warrior.', 'en', 'NRSV-CE', 'The Other Half-Tribe of Manasseh (West)'),
(6, 'Yos', 'Joshua', 17, 2, 'And allotments were made to the rest of the tribe of Manasseh, by their families, Abiezer, Helek, Asriel, Shechem, Hepher, and Shemida; these were the male descendants of Manasseh son of Joseph, by their families.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 3, 'Now Zelophehad son of Hepher son of Gilead son of Machir son of Manasseh had no sons, but only daughters; and these are the names of his daughters: Mahlah, Noah, Hoglah, Milcah, and Tirzah.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 4, 'They came before the priest Eleazar and Joshua son of Nun and the leaders, and said, "The LORD commanded Moses to give us an inheritance along with our male kin." So according to the commandment of the LORD he gave them an inheritance among the kinsmen of their father.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 5, 'Thus there fell to Manasseh ten portions, besides the land of Gilead and Bashan, which is on the other side of the Jordan,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 6, 'because the daughters of Manasseh received an inheritance along with his sons. The land of Gilead was allotted to the rest of the Manassites.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 7, 'The territory of Manasseh reached from Asher to Michmethath, which is east of Shechem; then the boundary goes along southward to the inhabitants of En-tappuah.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 8, 'The land of Tappuah belonged to Manasseh, but the town of Tappuah on the boundary of Manasseh belonged to the Ephraimites.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 9, 'Then the boundary went down to the Wadi Kanah. The towns here, to the south of the wadi, among the towns of Manasseh, belong to Ephraim. Then the boundary of Manasseh goes along the north side of the wadi and ends at the sea.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 10, 'The land to the south is Ephraim"s and that to the north is Manasseh"s, with the sea forming its boundary; on the north Asher is reached, and on the east Issachar.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 11, 'Within Issachar and Asher, Manasseh had Beth-shean and its villages, Ibleam and its villages, the inhabitants of Dor and its villages, the inhabitants of En-dor and its villages, the inhabitants of Taanach and its villages, and the inhabitants of Megiddo and its villages (the third is Naphath).', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 12, 'Yet the Manassites could not take possession of those towns; but the Canaanites continued to live in that land.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 13, 'But when the Israelites grew strong, they put the Canaanites to forced labor, but did not utterly drive them out.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 14, 'The tribe of Joseph spoke to Joshua, saying, "Why have you given me but one lot and one portion as an inheritance, since we are a numerous people, whom all along the LORD has blessed?"', 'en', 'NRSV-CE', 'The Tribe of Joseph Protests'),
(6, 'Yos', 'Joshua', 17, 15, 'And Joshua said to them, "If you are a numerous people, go up to the forest, and clear ground there for yourselves in the land of the Perizzites and the Rephaim, since the hill country of Ephraim is too narrow for you."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 16, 'The tribe of Joseph said, "The hill country is not enough for us; yet all the Canaanites who live in the plain have chariots of iron, both those in Beth-shean and its villages and those in the Valley of Jezreel."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 17, 'Then Joshua said to the house of Joseph, to Ephraim and Manasseh, "You are indeed a numerous people, and have great power; you shall not have one lot only,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 17, 18, 'but the hill country shall be yours, for though it is a forest, you shall clear it and possess it to its farthest borders; for you shall drive out the Canaanites, though they have chariots of iron, and though they are strong."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 18, 1, 'Then the whole congregation of the Israelites assembled at Shiloh, and set up the tent of meeting there. The land lay subdued before them.', 'en', 'NRSV-CE', 'The Territories of the Remaining Tribes'),
(6, 'Yos', 'Joshua', 18, 2, 'There remained among the Israelites seven tribes whose inheritance had not yet been apportioned.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 3, 'So Joshua said to the Israelites, "How long will you be slack about going in and taking possession of the land that the LORD, the God of your ancestors, has given you?', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 4, 'Provide three men from each tribe, and I will send them out that they may begin to go throughout the land, writing a description of it with a view to their inheritances. Then come back to me.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 5, 'They shall divide it into seven portions, Judah continuing in its territory on the south, and the house of Joseph in their territory on the north.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 6, 'You shall describe the land in seven divisions and bring the description here to me; and I will cast lots for you here before the LORD our God.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 7, 'The Levites have no portion among you, for the priesthood of the LORD is their heritage; and Gad and Reuben and the half-tribe of Manasseh have received their inheritance beyond the Jordan eastward, which Moses the servant of the LORD gave them."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 8, 'So the men started on their way; and Joshua charged those who went to write the description of the land, saying, "Go throughout the land and write a description of it, and come back to me; and I will cast lots for you here before the LORD in Shiloh."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 9, 'So the men went and traversed the land and set down in a book a description of it by towns in seven divisions; then they came back to Joshua in the camp at Shiloh,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 10, 'and Joshua cast lots for them in Shiloh before the LORD; and there Joshua apportioned the land to the Israelites, to each a portion.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 11, 'The lot of the tribe of Benjamin according to its families came up, and the territory allotted to it fell between the tribe of Judah and the tribe of Joseph.', 'en', 'NRSV-CE', 'The Territory of Benjamin'),
(6, 'Yos', 'Joshua', 18, 12, 'On the north side their boundary began at the Jordan; then the boundary goes up to the slope of Jericho on the north, then up through the hill country westward; and it ends at the wilderness of Beth-aven.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 13, 'From there the boundary passes along southward in the direction of Luz, to the slope of Luz (that is, Bethel), then the boundary goes down to Ataroth-addar, on the mountain that lies south of Lower Beth-horon.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 14, 'Then the boundary goes in another direction, turning on the western side southward from the mountain that lies to the south, opposite Beth-horon, and it ends at Kiriath-baal (that is, Kiriath-jearim), a town belonging to the tribe of Judah. This forms the western side.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 15, 'The southern side begins at the outskirts of Kiriath-jearim; and the boundary goes from there to Ephron, to the spring of the Waters of Nephtoah;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 16, 'then the boundary goes down to the border of the mountain that overlooks the valley of the son of Hinnom, which is at the north end of the valley of Rephaim; and it then goes down the valley of Hinnom, south of the slope of the Jebusites, and downward to En-rogel;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 17, 'then it bends in a northerly direction going on to En-shemesh, and from there goes to Geliloth, which is opposite the ascent of Adummim; then it goes down to the Stone of Bohan, Reuben"s son;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 18, 'and passing on to the north of the slope of Beth-arabah it goes down to the Arabah;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 19, 'then the boundary passes on to the north of the slope of Beth-hoglah; and the boundary ends at the northern bay of the Dead Sea, at the south end of the Jordan: this is the southern border.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 20, 'The Jordan forms its boundary on the eastern side. This is the inheritance of the tribe of Benjamin, according to its families, boundary by boundary all around.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 21, 'Now the towns of the tribe of Benjamin according to their families were Jericho, Beth-hoglah, Emek-keziz,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 22, 'Beth-arabah, Zemaraim, Bethel,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 23, 'Avvim, Parah, Ophrah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 24, 'Chephar-ammoni, Ophni, and Geba--twelve towns with their villages:', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 25, 'Gibeon, Ramah, Beeroth,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 26, 'Mizpeh, Chephirah, Mozah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 27, 'Rekem, Irpeel, Taralah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 18, 28, 'Zela, Haeleph, Jebus (that is, Jerusalem), Gibeah and Kiriath-jearim--fourteen towns with their villages. This is the inheritance of the tribe of Benjamin according to its families.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 19, 1, 'The second lot came out for Simeon, for the tribe of Simeon, according to its families; its inheritance lay within the inheritance of the tribe of Judah.', 'en', 'NRSV-CE', 'The Territory of Simeon'),
(6, 'Yos', 'Joshua', 19, 2, 'It had for its inheritance Beer-sheba, Sheba, Moladah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 3, 'Hazar-shual, Balah, Ezem,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 4, 'Eltolad, Bethul, Hormah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 5, 'Ziklag, Beth-marcaboth, Hazar-susah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 6, 'Beth-lebaoth, and Sharuhen--thirteen towns with their villages;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 7, 'Ain, Rimmon, Ether, and Ashan--four towns with their villages;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 8, 'together with all the villages all around these towns as far as Baalath-beer, Ramah of the Negeb. This was the inheritance of the tribe of Simeon according to its families.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 9, 'The inheritance of the tribe of Simeon formed part of the territory of Judah; because the portion of the tribe of Judah was too large for them, the tribe of Simeon obtained an inheritance within their inheritance.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 10, 'The third lot came up for the tribe of Zebulun, according to its families. The boundary of its inheritance reached as far as Sarid;', 'en', 'NRSV-CE', 'The Territory of Zebulun'),
(6, 'Yos', 'Joshua', 19, 11, 'then its boundary goes up westward, and on to Maralah, and touches Dabbesheth, then the wadi that is east of Jokneam;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 12, 'from Sarid it goes in the other direction eastward toward the sunrise to the boundary of Chisloth-tabor; from there it goes to Daberath, then up to Japhia;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 13, 'from there it passes along on the east toward the sunrise to Gath-hepher, to Eth-kazin, and going on to Rimmon it bends toward Neah;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 14, 'then on the north the boundary makes a turn to Hannathon, and it ends at the valley of Iphtah-el;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 15, 'and Kattath, Nahalal, Shimron, Idalah, and Bethlehem--twelve towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 16, 'This is the inheritance of the tribe of Zebulun, according to its families--these towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 17, 'The fourth lot came out for Issachar, for the tribe of Issachar, according to its families.', 'en', 'NRSV-CE', 'The Territory of Issachar'),
(6, 'Yos', 'Joshua', 19, 18, 'Its territory included Jezreel, Chesulloth, Shunem,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 19, 'Hapharaim, Shion, Anaharath,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 20, 'Rabbith, Kishion, Ebez,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 21, 'Remeth, En-gannim, En-haddah, Beth-pazzez;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 22, 'the boundary also touches Tabor, Shahazumah, and Beth-shemesh, and its boundary ends at the Jordan--sixteen towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 23, 'This is the inheritance of the tribe of Issachar, according to its families--the towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 24, 'The fifth lot came out for the tribe of Asher according to its families.', 'en', 'NRSV-CE', 'The Territory of Asher'),
(6, 'Yos', 'Joshua', 19, 25, 'Its boundary included Helkath, Hali, Beten, Achshaph,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 26, 'Allammelech, Amad, and Mishal; on the west it touches Carmel and Shihor-libnath,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 27, 'then it turns eastward, goes to Beth-dagon, and touches Zebulun and the valley of Iphtah-el northward to Beth-emek and Neiel; then it continues in the north to Cabul,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 28, 'Ebron, Rehob, Hammon, Kanah, as far as Great Sidon;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 29, 'then the boundary turns to Ramah, reaching to the fortified city of Tyre; then the boundary turns to Hosah, and it ends at the sea; Mahalab, Achzib,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 30, 'Ummah, Aphek, and Rehob--twenty-two towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 31, 'This is the inheritance of the tribe of Asher according to its families--these towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 32, 'The sixth lot came out for the tribe of Naphtali, for the tribe of Naphtali, according to its families.', 'en', 'NRSV-CE', 'The Territory of Naphtali'),
(6, 'Yos', 'Joshua', 19, 33, 'And its boundary ran from Heleph, from the oak in Zaanannim, and Adami-nekeb, and Jabneel, as far as Lakkum; and it ended at the Jordan;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 34, 'then the boundary turns westward to Aznoth-tabor, and goes from there to Hukkok, touching Zebulun at the south, and Asher on the west, and Judah on the east at the Jordan.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 35, 'The fortified towns are Ziddim, Zer, Hammath, Rakkath, Chinnereth,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 36, 'Adamah, Ramah, Hazor,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 37, 'Kedesh, Edrei, En-hazor,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 38, 'Iron, Migdal-el, Horem, Beth-anath, and Beth-shemesh--nineteen towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 39, 'This is the inheritance of the tribe of Naphtali according to its families--the towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 40, 'The seventh lot came out for the tribe of Dan, according to its families.', 'en', 'NRSV-CE', 'The Territory of Dan'),
(6, 'Yos', 'Joshua', 19, 41, 'The territory of its inheritance included Zorah, Eshtaol, Ir-shemesh,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 42, 'Shaalabbin, Aijalon, Ithlah,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 43, 'Elon, Timnah, Ekron,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 44, 'Eltekeh, Gibbethon, Baalath,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 45, 'Jehud, Bene-berak, Gath-rimmon,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 46, 'Me-jarkon, and Rakkon at the border opposite Joppa.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 47, 'When the territory of the Danites was lost to them, the Danites went up and fought against Leshem, and after capturing it and putting it to the sword, they took possession of it and settled in it, calling Leshem, Dan, after their ancestor Dan.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 48, 'This is the inheritance of the tribe of Dan, according to their families--these towns with their villages.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 49, 'When they had finished distributing the several territories of the land as inheritances, the Israelites gave an inheritance among them to Joshua son of Nun.', 'en', 'NRSV-CE', 'Joshua"s Inheritance'),
(6, 'Yos', 'Joshua', 19, 50, 'By command of the LORD they gave him the town that he asked for, Timnath-serah in the hill country of Ephraim; he rebuilt the town, and settled in it.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 19, 51, 'These are the inheritances that the priest Eleazar and Joshua son of Nun and the heads of the families of the tribes of the Israelites distributed by lot at Shiloh before the LORD, at the entrance of the tent of meeting. So they finished dividing the land.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 20, 1, 'Then the LORD spoke to Joshua, saying,', 'en', 'NRSV-CE', 'The Cities of Refuge'),
(6, 'Yos', 'Joshua', 20, 2, '"Say to the Israelites, "Appoint the cities of refuge, of which I spoke to you through Moses,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 20, 3, 'so that anyone who kills a person without intent or by mistake may flee there; they shall be for you a refuge from the avenger of blood.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 20, 4, 'The slayer shall flee to one of these cities and shall stand at the entrance of the gate of the city, and explain the case to the elders of that city; then the fugitive shall be taken into the city, and given a place, and shall remain with them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 20, 5, 'And if the avenger of blood is in pursuit, they shall not give up the slayer, because the neighbor was killed by mistake, there having been no enmity between them before.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 20, 6, 'The slayer shall remain in that city until there is a trial before the congregation, until the death of the one who is high priest at the time: then the slayer may return home, to the town in which the deed was done.""', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 20, 7, 'So they set apart Kedesh in Galilee in the hill country of Naphtali, and Shechem in the hill country of Ephraim, and Kiriath-arba (that is, Hebron) in the hill country of Judah.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 20, 8, 'And beyond the Jordan east of Jericho, they appointed Bezer in the wilderness on the tableland, from the tribe of Reuben, and Ramoth in Gilead, from the tribe of Gad, and Golan in Bashan, from the tribe of Manasseh.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 20, 9, 'These were the cities designated for all the Israelites, and for the aliens residing among them, that anyone who killed a person without intent could flee there, so as not to die by the hand of the avenger of blood, until there was a trial before the congregation.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 21, 1, 'Then the heads of the families of the Levites came to the priest Eleazar and to Joshua son of Nun and to the heads of the families of the tribes of the Israelites;', 'en', 'NRSV-CE', 'Cities Allotted to the Levites'),
(6, 'Yos', 'Joshua', 21, 2, 'they said to them at Shiloh in the land of Canaan, "The LORD commanded through Moses that we be given towns to live in, along with their pasture lands for our livestock."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 3, 'So by command of the LORD the Israelites gave to the Levites the following towns and pasture lands out of their inheritance.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 4, 'The lot came out for the families of the Kohathites. So those Levites who were descendants of Aaron the priest received by lot thirteen towns from the tribes of Judah, Simeon, and Benjamin.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 5, 'The rest of the Kohathites received by lot ten towns from the families of the tribe of Ephraim, from the tribe of Dan, and the half-tribe of Manasseh.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 6, 'The Gershonites received by lot thirteen towns from the families of the tribe of Issachar, from the tribe of Asher, from the tribe of Naphtali, and from the half-tribe of Manasseh in Bashan.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 7, 'The Merarites according to their families received twelve towns from the tribe of Reuben, the tribe of Gad, and the tribe of Zebulun.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 8, 'These towns and their pasture lands the Israelites gave by lot to the Levites, as the LORD had commanded through Moses.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 9, 'Out of the tribe of Judah and the tribe of Simeon they gave the following towns mentioned by name,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 10, 'which went to the descendants of Aaron, one of the families of the Kohathites who belonged to the Levites, since the lot fell to them first.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 11, 'They gave them Kiriath-arba (Arba being the father of Anak), that is Hebron, in the hill country of Judah, along with the pasture lands around it.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 12, 'But the fields of the town and its villages had been given to Caleb son of Jephunneh as his holding.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 13, 'To the descendants of Aaron the priest they gave Hebron, the city of refuge for the slayer, with its pasture lands, Libnah with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 14, 'Jattir with its pasture lands, Eshtemoa with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 15, 'Holon with its pasture lands, Debir with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 16, 'Ain with its pasture lands, Juttah with its pasture lands, and Beth-shemesh with its pasture lands--nine towns out of these two tribes.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 17, 'Out of the tribe of Benjamin: Gibeon with its pasture lands, Geba with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 18, 'Anathoth with its pasture lands, and Almon with its pasture lands--four towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 19, 'The towns of the descendants of Aaron--the priests--were thirteen in all, with their pasture lands.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 20, 'As to the rest of the Kohathites belonging to the Kohathite families of the Levites, the towns allotted to them were out of the tribe of Ephraim.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 21, 'To them were given Shechem, the city of refuge for the slayer, with its pasture lands in the hill country of Ephraim, Gezer with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 22, 'Kibzaim with its pasture lands, and Beth-horon with its pasture lands--four towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 23, 'Out of the tribe of Dan: Elteke with its pasture lands, Gibbethon with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 24, 'Aijalon with its pasture lands, Gath-rimmon with its pasture lands--four towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 25, 'Out of the half-tribe of Manasseh: Taanach with its pasture lands, and Gath-rimmon with its pasture lands--two towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 26, 'The towns of the families of the rest of the Kohathites were ten in all, with their pasture lands.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 27, 'To the Gershonites, one of the families of the Levites, were given out of the half-tribe of Manasseh, Golan in Bashan with its pasture lands, the city of refuge for the slayer, and Beeshterah with its pasture lands--two towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 28, 'Out of the tribe of Issachar: Kishion with its pasture lands, Daberath with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 29, 'Jarmuth with its pasture lands, En-gannim with its pasture lands--four towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 30, 'Out of the tribe of Asher: Mishal with its pasture lands, Abdon with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 31, 'Helkath with its pasture lands, and Rehob with its pasture lands--four towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 32, 'Out of the tribe of Naphtali: Kedesh in Galilee with its pasture lands, the city of refuge for the slayer, Hammoth-dor with its pasture lands, and Kartan with its pasture lands--three towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 33, 'The towns of the several families of the Gershonites were in all thirteen, with their pasture lands.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 34, 'To the rest of the Levites--the Merarite families--were given out of the tribe of Zebulun: Jokneam with its pasture lands, Kartah with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 35, 'Dimnah with its pasture lands, Nahalal with its pasture lands--four towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 36, 'Out of the tribe of Reuben: Bezer with its pasture lands, Jahzah with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 37, 'Kedemoth with its pasture lands, and Mephaath with its pasture lands--four towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 38, 'Out of the tribe of Gad: Ramoth in Gilead with its pasture lands, the city of refuge for the slayer, Mahanaim with its pasture lands,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 39, 'Heshbon with its pasture lands, Jazer with its pasture lands--four towns in all.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 40, 'As for the towns of the several Merarite families, that is, the remainder of the families of the Levites, those allotted to them were twelve in all.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 41, 'The towns of the Levites within the holdings of the Israelites were in all forty-eight towns with their pasture lands.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 42, 'Each of these towns had its pasture lands around it; so it was with all these towns.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 43, 'Thus the LORD gave to Israel all the land that he swore to their ancestors that he would give them; and having taken possession of it, they settled there.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 44, 'And the LORD gave them rest on every side just as he had sworn to their ancestors; not one of all their enemies had withstood them, for the LORD had given all their enemies into their hands.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 21, 45, 'Not one of all the good promises that the LORD had made to the house of Israel had failed; all came to pass.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 22, 1, 'Then Joshua summoned the Reubenites, the Gadites, and the half-tribe of Manasseh,', 'en', 'NRSV-CE', 'The Eastern Tribes Return to Their Territory'),
(6, 'Yos', 'Joshua', 22, 2, 'and said to them, "You have observed all that Moses the servant of the LORD commanded you, and have obeyed me in all that I have commanded you;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 3, 'you have not forsaken your kindred these many days, down to this day, but have been careful to keep the charge of the LORD your God.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 4, 'And now the LORD your God has given rest to your kindred, as he promised them; therefore turn and go to your tents in the land where your possession lies, which Moses the servant of the LORD gave you on the other side of the Jordan.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 5, 'Take good care to observe the commandment and instruction that Moses the servant of the LORD commanded you, to love the LORD your God, to walk in all his ways, to keep his commandments, and to hold fast to him, and to serve him with all your heart and with all your soul."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 6, 'So Joshua blessed them and sent them away, and they went to their tents.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 7, 'Now to the one half of the tribe of Manasseh Moses had given a possession in Bashan; but to the other half Joshua had given a possession beside their fellow Israelites in the land west of the Jordan. And when Joshua sent them away to their tents and blessed them,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 8, 'he said to them, "Go back to your tents with much wealth, and with very much livestock, with silver, gold, bronze, and iron, and with a great quantity of clothing; divide the spoil of your enemies with your kindred."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 9, 'So the Reubenites and the Gadites and the half-tribe of Manasseh returned home, parting from the Israelites at Shiloh, which is in the land of Canaan, to go to the land of Gilead, their own land of which they had taken possession by command of the LORD through Moses.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 10, 'When they came to the region near the Jordan that lies in the land of Canaan, the Reubenites and the Gadites and the half-tribe of Manasseh built there an altar by the Jordan, an altar of great size.', 'en', 'NRSV-CE', 'A Memorial Altar East of the Jordan'),
(6, 'Yos', 'Joshua', 22, 11, 'The Israelites heard that the Reubenites and the Gadites and the half-tribe of Manasseh had built an altar at the frontier of the land of Canaan, in the region near the Jordan, on the side that belongs to the Israelites.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 12, 'And when the people of Israel heard of it, the whole assembly of the Israelites gathered at Shiloh, to make war against them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 13, 'Then the Israelites sent the priest Phinehas son of Eleazar to the Reubenites and the Gadites and the half-tribe of Manasseh, in the land of Gilead,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 14, 'and with him ten chiefs, one from each of the tribal families of Israel, every one of them the head of a family among the clans of Israel.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 15, 'They came to the Reubenites, the Gadites, and the half-tribe of Manasseh, in the land of Gilead, and they said to them,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 16, '"Thus says the whole congregation of the LORD, "What is this treachery that you have committed against the God of Israel in turning away today from following the LORD, by building yourselves an altar today in rebellion against the LORD?', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 17, 'Have we not had enough of the sin at Peor from which even yet we have not cleansed ourselves, and for which a plague came upon the congregation of the LORD,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 18, 'that you must turn away today from following the LORD! If you rebel against the LORD today, he will be angry with the whole congregation of Israel tomorrow.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 19, 'But now, if your land is unclean, cross over into the LORD"s land where the LORD"s tabernacle now stands, and take for yourselves a possession among us; only do not rebel against the LORD, or rebel against us by building yourselves an altar other than the altar of the LORD our God.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 20, 'Did not Achan son of Zerah break faith in the matter of the devoted things, and wrath fell upon all the congregation of Israel? And he did not perish alone for his iniquity!""', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 21, 'Then the Reubenites, the Gadites, and the half-tribe of Manasseh said in answer to the heads of the families of Israel,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 22, '"The LORD, God of gods! The LORD, God of gods! He knows; and let Israel itself know! If it was in rebellion or in breach of faith toward the LORD, do not spare us today', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 23, 'for building an altar to turn away from following the LORD; or if we did so to offer burnt offerings or grain offerings or offerings of well-being on it, may the LORD himself take vengeance.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 24, 'No! We did it from fear that in time to come your children might say to our children, "What have you to do with the LORD, the God of Israel?', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 25, 'For the LORD has made the Jordan a boundary between us and you, you Reubenites and Gadites; you have no portion in the LORD." So your children might make our children cease to worship the LORD.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 26, 'Therefore we said, "Let us now build an altar, not for burnt offering, nor for sacrifice,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 27, 'but to be a witness between us and you, and between the generations after us, that we do perform the service of the LORD in his presence with our burnt offerings and sacrifices and offerings of well-being; so that your children may never say to our children in time to come, "You have no portion in the LORD.""', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 28, 'And we thought, If this should be said to us or to our descendants in time to come, we could say, "Look at this copy of the altar of the LORD, which our ancestors made, not for burnt offerings, nor for sacrifice, but to be a witness between us and you."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 29, 'Far be it from us that we should rebel against the LORD, and turn away this day from following the LORD by building an altar for burnt offering, grain offering, or sacrifice, other than the altar of the LORD our God that stands before his tabernacle!"', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 30, 'When the priest Phinehas and the chiefs of the congregation, the heads of the families of Israel who were with him, heard the words that the Reubenites and the Gadites and the Manassites spoke, they were satisfied.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 31, 'The priest Phinehas son of Eleazar said to the Reubenites and the Gadites and the Manassites, "Today we know that the LORD is among us, because you have not committed this treachery against the LORD; now you have saved the Israelites from the hand of the LORD."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 32, 'Then the priest Phinehas son of Eleazar and the chiefs returned from the Reubenites and the Gadites in the land of Gilead to the land of Canaan, to the Israelites, and brought back word to them.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 33, 'The report pleased the Israelites; and the Israelites blessed God and spoke no more of making war against them, to destroy the land where the Reubenites and the Gadites were settled.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 22, 34, 'The Reubenites and the Gadites called the altar Witness; "For," said they, "it is a witness between us that the LORD is God."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 23, 1, 'A long time afterward, when the LORD had given rest to Israel from all their enemies all around, and Joshua was old and well advanced in years,', 'en', 'NRSV-CE', 'Joshua Exhorts the People'),
(6, 'Yos', 'Joshua', 23, 2, 'Joshua summoned all Israel, their elders and heads, their judges and officers, and said to them, "I am now old and well advanced in years;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 3, 'and you have seen all that the LORD your God has done to all these nations for your sake, for it is the LORD your God who has fought for you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 4, 'I have allotted to you as an inheritance for your tribes those nations that remain, along with all the nations that I have already cut off, from the Jordan to the Great Sea in the west.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 5, 'The LORD your God will push them back before you, and drive them out of your sight; and you shall possess their land, as the LORD your God promised you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 6, 'Therefore be very steadfast to observe and do all that is written in the book of the law of Moses, turning aside from it neither to the right nor to the left,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 7, 'so that you may not be mixed with these nations left here among you, or make mention of the names of their gods, or swear by them, or serve them, or bow yourselves down to them,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 8, 'but hold fast to the LORD your God, as you have done to this day.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 9, 'For the LORD has driven out before you great and strong nations; and as for you, no one has been able to withstand you to this day.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 10, 'One of you puts to flight a thousand, since it is the LORD your God who fights for you, as he promised you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 11, 'Be very careful, therefore, to love the LORD your God.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 12, 'For if you turn back, and join the survivors of these nations left here among you, and intermarry with them, so that you marry their women and they yours,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 13, 'know assuredly that the LORD your God will not continue to drive out these nations before you; but they shall be a snare and a trap for you, a scourge on your sides, and thorns in your eyes, until you perish from this good land that the LORD your God has given you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 14, '"And now I am about to go the way of all the earth, and you know in your hearts and souls, all of you, that not one thing has failed of all the good things that the LORD your God promised concerning you; all have come to pass for you, not one of them has failed.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 15, 'But just as all the good things that the LORD your God promised concerning you have been fulfilled for you, so the LORD will bring upon you all the bad things, until he has destroyed you from this good land that the LORD your God has given you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 23, 16, 'If you transgress the covenant of the LORD your God, which he enjoined on you, and go and serve other gods and bow down to them, then the anger of the LORD will be kindled against you, and you shall perish quickly from the good land that he has given to you."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(6, 'Yos', 'Joshua', 24, 1, 'Then Joshua gathered all the tribes of Israel to Shechem, and summoned the elders, the heads, the judges, and the officers of Israel; and they presented themselves before God.', 'en', 'NRSV-CE', 'The Tribes Renew the Covenant'),
(6, 'Yos', 'Joshua', 24, 2, 'And Joshua said to all the people, "Thus says the LORD, the God of Israel: Long ago your ancestors--Terah and his sons Abraham and Nahor--lived beyond the Euphrates and served other gods.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 3, 'Then I took your father Abraham from beyond the River and led him through all the land of Canaan and made his offspring many. I gave him Isaac;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 4, 'and to Isaac I gave Jacob and Esau. I gave Esau the hill country of Seir to possess, but Jacob and his children went down to Egypt.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 5, 'Then I sent Moses and Aaron, and I plagued Egypt with what I did in its midst; and afterwards I brought you out.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 6, 'When I brought your ancestors out of Egypt, you came to the sea; and the Egyptians pursued your ancestors with chariots and horsemen to the Red Sea.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 7, 'When they cried out to the LORD, he put darkness between you and the Egyptians, and made the sea come upon them and cover them; and your eyes saw what I did to Egypt. Afterwards you lived in the wilderness a long time.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 8, 'Then I brought you to the land of the Amorites, who lived on the other side of the Jordan; they fought with you, and I handed them over to you, and you took possession of their land, and I destroyed them before you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 9, 'Then King Balak son of Zippor of Moab, set out to fight against Israel. He sent and invited Balaam son of Beor to curse you,', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 10, 'but I would not listen to Balaam; therefore he blessed you; so I rescued you out of his hand.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 11, 'When you went over the Jordan and came to Jericho, the citizens of Jericho fought against you, and also the Amorites, the Perizzites, the Canaanites, the Hittites, the Girgashites, the Hivites, and the Jebusites; and I handed them over to you.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 12, 'I sent the hornet ahead of you, which drove out before you the two kings of the Amorites; it was not by your sword or by your bow.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 13, 'I gave you a land on which you had not labored, and towns that you had not built, and you live in them; you eat the fruit of vineyards and oliveyards that you did not plant.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 14, '"Now therefore revere the LORD, and serve him in sincerity and in faithfulness; put away the gods that your ancestors served beyond the River and in Egypt, and serve the LORD.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 15, 'Now if you are unwilling to serve the LORD, choose this day whom you will serve, whether the gods your ancestors served in the region beyond the River or the gods of the Amorites in whose land you are living; but as for me and my household, we will serve the LORD."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 16, 'Then the people answered, "Far be it from us that we should forsake the LORD to serve other gods;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 17, 'for it is the LORD our God who brought us and our ancestors up from the land of Egypt, out of the house of slavery, and who did those great signs in our sight. He protected us along all the way that we went, and among all the peoples through whom we passed;', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 18, 'and the LORD drove out before us all the peoples, the Amorites who lived in the land. Therefore we also will serve the LORD, for he is our God."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 19, 'But Joshua said to the people, "You cannot serve the LORD, for he is a holy God. He is a jealous God; he will not forgive your transgressions or your sins.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 20, 'If you forsake the LORD and serve foreign gods, then he will turn and do you harm, and consume you, after having done you good."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 21, 'And the people said to Joshua, "No, we will serve the LORD!"', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 22, 'Then Joshua said to the people, "You are witnesses against yourselves that you have chosen the LORD, to serve him." And they said, "We are witnesses."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 23, 'He said, "Then put away the foreign gods that are among you, and incline your hearts to the LORD, the God of Israel."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 24, 'The people said to Joshua, "The LORD our God we will serve, and him we will obey."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 25, 'So Joshua made a covenant with the people that day, and made statutes and ordinances for them at Shechem.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 26, 'Joshua wrote these words in the book of the law of God; and he took a large stone, and set it up there under the oak in the sanctuary of the LORD.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 27, 'Joshua said to all the people, "See, this stone shall be a witness against us; for it has heard all the words of the LORD that he spoke to us; therefore it shall be a witness against you, if you deal falsely with your God."', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 28, 'So Joshua sent the people away to their inheritances.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 29, 'After these things Joshua son of Nun, the servant of the LORD, died, being one hundred ten years old.', 'en', 'NRSV-CE', 'Death of Joshua and Eleazar'),
(6, 'Yos', 'Joshua', 24, 30, 'They buried him in his own inheritance at Timnath-serah, which is in the hill country of Ephraim, north of Mount Gaash.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 31, 'Israel served the LORD all the days of Joshua, and all the days of the elders who outlived Joshua and had known all the work that the LORD did for Israel.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 32, 'The bones of Joseph, which the Israelites had brought up from Egypt, were buried at Shechem, in the portion of ground that Jacob had bought from the children of Hamor, the father of Shechem, for one hundred pieces of money; it became an inheritance of the descendants of Joseph.', 'en', 'NRSV-CE', NULL),
(6, 'Yos', 'Joshua', 24, 33, 'Eleazar son of Aaron died; and they buried him at Gibeah, the town of his son Phinehas, which had been given him in the hill country of Ephraim.', 'en', 'NRSV-CE', NULL);
